window.POO=window.POO||{};window.POO.data=window.POO.data||{};window.POO.data.questions=[{"q":"Las fases genéricas del desarrollo del software son:","o":["Análisis, modelado, codificación y testeo.","Análisis, diseño, codificación, pruebas y mantenimiento.","Diseño, escritura y verificación.","Verificación y validación."],"h":["Son las etapas clásicas del ciclo de vida.","Incluye la fase de construcción del sistema.","La última fase adapta el sistema a nuevos requisitos."],"c":1,"e":"Las etapas principales de cualquier ciclo de vida son: Análisis, Diseño, Codificación, Prueba y Mantenimiento.","d":1,"id":"q001","unit":"UF2406-UD1"},{"q":"¿Cuál de estas es una ventaja del ciclo de vida clásico (en cascada)?","o":["Es fácil arreglar los errores.","Se obtiene el producto al final.","La planificación es sencilla.","Hay muchos indicadores del ritmo de trabajo."],"h":["Es el modelo propuesto por Royce en 1970.","Trabaja en base a documentos formales.","Permite trabajar con empleados de menor cualificación."],"c":2,"e":"El modelo en cascada tiene como ventaja que la planificación del proyecto es sencilla y fácil de hacer, y la calidad es alta si se aplica correctamente.","d":2,"id":"q002","unit":"UF2406-UD1"},{"q":"¿Cuál NO es una ventaja del ciclo de vida en espiral?","o":["Es difícil evaluar los riesgos.","No necesita una definición completa de los requisitos al comienzo.","El riesgo en general es menor.","Es más fácil validar los requisitos."],"h":["Es un modelo evolutivo e iterativo.","Entrega productos desde la primera iteración.","La incertidumbre limita la estimación adecuada."],"c":0,"e":"La dificultad para llevar a cabo una evaluación correcta de los riesgos es un inconveniente del modelo en espiral, no una ventaja.","d":2,"id":"q003","unit":"UF2406-UD1"},{"q":"¿Cuál de las siguientes NO es una técnica de extracción de requisitos?","o":["El modelado de requisitos durante el análisis.","Las entrevistas y Brainstorming.","El Desarrollo Conjunto de Aplicaciones (JAD).","Los prototipos."],"h":["Las técnicas de extracción buscan descubrir necesidades directamente.","El modelado es una fase posterior de representación.","JAD y Brainstorming son técnicas de obtención directa."],"c":0,"e":"El modelado de requisitos es una fase de representación y estructuración, no una técnica de extracción como las entrevistas, JAD, brainstorming o prototipos.","d":2,"id":"q004","unit":"UF2406-UD1"},{"q":"La matriz de trazabilidad:","o":["Se usa para comprobar que los requisitos del proyecto se están cumpliendo.","Nos indica los errores de diseño.","Sirve para que el usuario tenga una buena experiencia de uso.","Indica el número de clases de un proyecto."],"h":["Es un documento en forma de tabla.","Correlaciona dos documentos (ej. requisitos y casos de prueba).","Determina la integridad de la relación entre requisitos."],"c":0,"e":"Una matriz de trazabilidad se utiliza para comprobar si se están cumpliendo los requisitos actuales del proyecto y para rastrear su origen y evolución.","d":2,"id":"q005","unit":"UF2406-UD1"},{"q":"La metodología Métrica:","o":["Es la metodología oficial de las administraciones públicas en España.","Es obligatorio utilizarla en toda España, salvo en el País Vasco y Navarra.","No tiene fase de análisis de requisitos.","No es orientada a objetos."],"h":["Sistematiza todas las actividades del ciclo de vida.","Incluye procesos que no forman parte estrictamente del ciclo de vida (como gestión de configuración).","Tiene en cuenta tecnologías para sistemas distribuidos."],"c":0,"e":"La metodología Métrica es la metodología oficial de desarrollo de aplicaciones de la administración española.","d":1,"id":"q006","unit":"UF2406-UD1"},{"q":"¿Cuáles NO son objetivos de una herramienta CASE?","o":["Facilitar la realización de prototipos.","Eliminar la necesidad de esfuerzo de programación.","Mejorar y estandarizar la documentación.","Facilitar la reutilización de componentes."],"h":["Automatizan tareas del ciclo de vida.","Mejoran la productividad del ingeniero.","No eliminan la necesidad de programar, solo la facilitan y organizan."],"c":1,"e":"Las herramientas CASE facilitan y automatizan tareas, pero no eliminan la necesidad de esfuerzo de programación por parte del desarrollador.","d":2,"id":"q007","unit":"UF2406-UD1"},{"q":"Las herramientas de ingeniería del software:","o":["Trabajan solamente a bajo nivel.","Trabajan a nivel medio de la organización.","Trabajan fundamentalmente a alto nivel.","Modelan la organización a nivel táctico."],"h":["Se centran en análisis, diseño y validación.","Se utilizan en el modelado de procesos de negocio.","Proporcionan una visión global del sistema."],"c":2,"e":"Las herramientas de ingeniería del software actúan fundamentalmente a alto nivel, centrándose sobre todo en las actividades de análisis, diseño y validación del software.","d":2,"id":"q008","unit":"UF2406-UD1"},{"q":"Sobre un IDE (Entorno de Desarrollo Integrado):","o":["Está perfectamente claro qué es un IDE y qué no lo es.","No suelen incorporar un navegador de clases.","No están diseñados para aumentar la productividad de los programadores.","Todas las anteriores son falsas."],"h":["Proporciona servicios integrales (editor, compilador, depurador).","Maximiza la productividad.","El límite exacto de qué es un IDE no está rígidamente definido."],"c":3,"e":"Un IDE sí incorpora navegador de clases, sí está diseñado para aumentar la productividad, y el límite de qué es un IDE no está perfectamente definido. Por tanto, a, b y c son falsas.","d":2,"id":"q009","unit":"UF2406-UD1"},{"q":"Sobre los prototipos:","o":["No deben ser mostrados al usuario final.","Deben centrarse en la arquitectura de sistema en vez de en su aspecto.","No requieren de ninguna herramienta en especial.","Su propósito es que los usuarios finales puedan evaluar las propuestas de los desarrolladores."],"h":["Son versiones reducidas de la aplicación final.","Sirven para obtener y validar requisitos.","Permiten experimentar con el diseño antes de la implementación final."],"c":3,"e":"El propósito de un prototipo es permitir que los usuarios del software puedan evaluar las propuestas de los desarrolladores y experimentar con dichos diseños.","d":1,"id":"q010","unit":"UF2406-UD1"},{"q":"Los tipos de modelos de estimación que hay son:","o":["Modelos de determinación de análisis, modelado, codificación y testeo.","Modelos matemáticos paramétricos, Estimación basada en la experiencia de experto, técnicas orientadas al aprendizaje y modelos dinámicos.","Modelos matemáticos paramétricos, Estimación basada en la experiencia de experto, técnicas orientadas al aprendizaje y modelos de verificación.","Modelos de Verificación y validación."],"h":["Clasificación basada en el enfoque de cálculo.","Incluye enfoques estadísticos y juicios humanos.","Consideran la variación temporal de los costes."],"c":1,"e":"Los cuatro grupos de métodos de estimación son: modelos paramétricos, basados en expertos, orientados al aprendizaje y modelos dinámicos.","d":2,"id":"q011","unit":"UF2406-UD2"},{"q":"¿Cuál de estos NO es un método de estimación?","o":["COCOMO.","Método de PUTNAM.","PERT.","MK II."],"h":["COCOMO y Putnam son modelos paramétricos de esfuerzo.","MK II es un método de puntos de función.","PERT es una técnica de diagramado de red."],"c":2,"e":"PERT es una herramienta de planificación y diagramado de actividades (ruta crítica), no un modelo de estimación de esfuerzo/coste como los otros.","d":3,"id":"q012","unit":"UF2406-UD2"},{"q":"Sobre el método COSMIC, indica la respuesta falsa:","o":["Es difícil evaluar los riesgos en él.","Es un método de evaluación de segunda generación.","Es un método abierto.","Se ajusta a la normativa ISO."],"h":["Se basa en principios fundamentales de ingeniería de software.","Es el primer método ajustado a la norma ISO/IEC 14143/1:2003.","Su documentación es gratuita y abierta."],"c":0,"e":"El método COSMIC es abierto, de segunda generación y se ajusta a la normativa ISO. No es una característica definitoria que sea \"difícil evaluar riesgos\"; de hecho, mejora la precisión de la estimación.","d":3,"id":"q013","unit":"UF2406-UD2"},{"q":"La actividad de planificación o programación de un proyecto, consiste en establecer la estructura temporal de...","o":["Las fases, actividades y tareas del proyecto, en función de los recursos de que se deseen.","Las fases del proyecto, en función de los recursos de que se disponga.","Las fases, actividades y tareas del proyecto, en función de los recursos de que se disponga.","Las fases de programación así como sus, actividades y tareas del proyecto, en función de los recursos de que se disponga."],"h":["Organiza el trabajo en el tiempo.","Considera fases, actividades y tareas de forma integral.","Depende de los recursos disponibles, no de los deseados."],"c":2,"e":"La planificación consiste en establecer la estructura temporal de las fases, actividades y tareas del proyecto, en función de los recursos de que se disponga.","d":1,"id":"q014","unit":"UF2406-UD2"},{"q":"Las actividades del método PERT:","o":["Se representan mediante cajas.","Se representan mediante flechas.","Se representan mediante rombos.","No se indican explícitamente en el diagrama."],"h":["PERT usa diagramas de red.","En la notación descrita en el texto, los nodos son eventos.","Las actividades se representan con cajas que contienen su nombre e información."],"c":0,"e":"Según el documento, en la construcción de diagramas PERT descrita, una actividad se representa por cajas que contienen el nombre de la actividad y alguna información adicional.","d":2,"id":"q015","unit":"UF2406-UD2"},{"q":"El seguimiento y control:","o":["Es fundamental en la gestión de un proyecto.","Se hace mediante el método COCOMO.","No es necesario en proyectos pequeños.","Se realiza mediante herramientas de dimensionamiento."],"h":["Asegura que el proyecto satisface sus objetivos en calidad, coste y tiempo.","Implica recopilar datos reales y contrastarlos con los estimados.","Es una parte fundamental de la Gestión de Proyectos."],"c":0,"e":"El seguimiento y control es una parte fundamental de la Gestión de Proyectos; se ha observado que el éxito de los proyectos radica en un adecuado seguimiento y control del mismo.","d":1,"id":"q016","unit":"UF2406-UD2"},{"q":"El resumen ejecutivo:","o":["Se presenta al comienzo del proyecto/informe.","Se comienza con la planificación.","Se presenta al final de proyecto.","Se presenta al finalizar la fase de diseño."],"h":["Da una visión general concisa.","Aparece al comienzo de un informe de gestión.","Ayuda a decidir si leer todo el informe o centrarse en una parte."],"c":0,"e":"El resumen ejecutivo se presenta al comienzo de un informe de gestión del proyecto para dar al lector una visión general concisa del propósito, resultados y problemas.","d":2,"id":"q017","unit":"UF2406-UD2"},{"q":"En la presentación de un informe:","o":["No hay que añadir la metodología.","Conviene estructurarlo adecuadamente.","Se puede obviar el formato para mayor velocidad.","No es necesario difundirlo entre el equipo."],"h":["Debe ser lo más conciso posible sin sacrificar calidad.","Debe dividirse en categorías claramente etiquetadas.","Hay que revisar errores tipográficos y de formato."],"c":1,"e":"Conviene estructurar el informe adecuadamente, dividir el contenido en categorías y cuidar el formato para guiar la atención de los lectores.","d":1,"id":"q018","unit":"UF2406-UD2"},{"q":"Las técnicas de formato a la hora de elaborar un informe:","o":["No son necesarias para hacer un informe.","Dependen de la organización y no del autor.","Son necesarias para poder presentarlo adecuadamente.","Modelan la organización a nivel táctico."],"h":["Guían la atención de los lectores.","Usan subtítulos y viñetas.","Ahorran tiempo a los lectores que buscan información específica."],"c":2,"e":"Las técnicas de formato son necesarias para presentar el informe adecuadamente, guiando la atención de los lectores con categorías claras, subtítulos y viñetas.","d":1,"id":"q019","unit":"UF2406-UD2"},{"q":"La retroalimentación regular (en el contexto del método Delphi) se refiere a:","o":["El director del proyecto indica quien lo hace bien y quien lo hace mal.","Deben centrarse en los fallos cometidos.","No requieren de reuniones específicas.","Los participantes comentan sus propias previsiones y las de los demás."],"h":["Es una característica clave del método Delphi.","Se anima a los expertos a revisar sus respuestas anteriores.","El grupo converge hacia la respuesta \"correcta\"."],"c":3,"e":"En la retroalimentación regular, los participantes comentan sus propias previsiones y las respuestas de los demás, revisando sus declaraciones anteriores a la luz de las opiniones del grupo.","d":2,"id":"q020","unit":"UF2406-UD2"},{"q":"Un navegador web es:","o":["Es un hardware que se utiliza para acceder a un ordenador.","Es un software que se utiliza para acceder a Internet.","Es un hardware que se utiliza para acceder a Internet.","Es un software para acceder a un ordenador."],"h":["Interpreta información de archivos y sitios web.","Permite visitar páginas y realizar acciones (iniciar sesión, ver multimedia).","Ejemplos: Chrome, Firefox, Edge."],"c":1,"e":"Un navegador web es un software que se utiliza para acceder a Internet, interpretar información de sitios web y permitir al usuario interactuar con ellos.","d":1,"id":"q021","unit":"UF2405-UD1"},{"q":"Se define una arquitectura web como...","o":["Un sistema que da como resultado información a los usuarios, con independencia de donde este ubicada esa información.","Es un sistema que no da como resultado información a los usuarios...","Es una combinación de sistemas que colaboran entre sí para dar como resultado a los usuarios información, con independencia de donde este ubicada la información.","Es una combinación de sistemas que son incapaces de colaborar entre sí..."],"h":["Implica colaboración entre sistemas (cliente, servidor, etc.).","El resultado final es información útil para el usuario.","La ubicación física de la información es transparente para el usuario."],"c":2,"e":"La arquitectura web se define como la combinación de sistemas que colaboran entre sí para dar como resultado información a los usuarios, con independencia de dónde esté ubicada dicha información.","d":1,"id":"q022","unit":"UF2405-UD1"},{"q":"Un servidor web se ejecuta durante:","o":["Todo el día.","365 días al año.","12 horas al día.","Todo el día los 365 días del año."],"h":["Mantiene a la espera de peticiones de clientes.","Almacena y transmite datos de un sitio.","Requiere un funcionamiento continuo y ininterrumpido."],"c":3,"e":"Un servidor web es un tipo de software que se instala y se ejecuta constantemente en un ordenador, todo el día los 365 días del año, manteniéndose a la espera de las peticiones del cliente.","d":1,"id":"q023","unit":"UF2405-UD1"},{"q":"¿Qué elementos forman parte de la arquitectura web básica?","o":["Cliente.","Cliente y servidor.","Servidor.","Ninguno de los anteriores."],"h":["Modelo básico de comunicación en red.","Uno solicita información, el otro responde.","Se conoce como arquitectura Cliente/Servidor."],"c":1,"e":"La arquitectura web básica se compone de un cliente (que solicita) y un servidor (que responde), formando el modelo fundamental Cliente/Servidor.","d":1,"id":"q024","unit":"UF2405-UD1"},{"q":"Ventajas de utilizar un cliente ligero:","o":["Información centralizada, menos coste de hardware, menos coste en administración.","Información centralizada, menos coste de hardware, menos coste en administración, consumo energético.","Información centralizada, menos coste de hardware, menos coste en administración, consumo energético, más seguro.","Información centralizada, menos coste en administración, consumo energético, más seguro."],"h":["El procesamiento pesado está en el servidor.","Requiere menos recursos locales (RAM, disco).","Mayor seguridad al no almacenar datos sensibles localmente."],"c":2,"e":"Las ventajas incluyen: información centralizada, menos coste de hardware, menos coste en administración, menor consumo energético y mayor seguridad.","d":2,"id":"q025","unit":"UF2405-UD1"},{"q":"¿A qué protocolo corresponde la función de transformar y dar significado a los mensajes intercambiados entre el Cliente y el Servidor?","o":["TCP/IP.","FTP.","HTTP.","NEWS."],"h":["Es el protocolo por defecto en la web.","Sus siglas son HyperText Transfer Protocol.","No guarda referencia a conexiones previas (es sin estado)."],"c":2,"e":"El protocolo HTTP es el que va a transformar y dar significado a los mensajes intercambiados entre el cliente (navegador) y el servidor web.","d":1,"id":"q026","unit":"UF2405-UD1"},{"q":"Los lenguajes estructurados son:","o":["XML, ASP, HTTP.","HTML Y CSS.","XML y HTTP.","FTP, XML y CSS."],"h":["Definen la estructura y el contenido de la página.","HTML es el principal lenguaje de marcado estructurado.","El documento los agrupa en esta categoría para la maquetación."],"c":1,"e":"El lenguaje HTML es un lenguaje estructurado utilizado para definir la estructura y el contenido de una página web (y CSS se asocia en el contexto de la pregunta a la presentación estructurada).","d":2,"id":"q027","unit":"UF2405-UD1"},{"q":"Los lenguajes de programación más utilizados en el desarrollo de aplicaciones web son principalmente:","o":["HTML, JSP, ASP Y PHP.","ASP, HTML, JAVASCRIPT, PHP y JSP.","FTP, ASP, PHP, JSP y JAVASCRIPT.","FTP, ASP, PHP, JSP y HTML."],"h":["Incluyen lenguajes de scripting y marcado.","El documento lista explícitamente estos cinco como los principales.","FTP es un protocolo de transferencia, no un lenguaje de programación."],"c":1,"e":"Los lenguajes de programación más utilizados en el desarrollo de aplicaciones web son principalmente: HTML, ASP, JAVASCRIPT, PHP y JSP.","d":1,"id":"q028","unit":"UF2405-UD1"},{"q":"Los lenguajes de programación más utilizados en el desarrollo de aplicaciones web son principalmente (enfoque en servidor/dinámico):","o":["ASP y PHP.","ASP y JAVASCRIPT.","PHP y JAVASCRIPT.","ASP y HTML."],"h":["Son lenguajes de script del lado del servidor muy populares.","Permiten crear páginas dinámicas e interactuar con bases de datos.","El documento los destaca como los principales en su categoría de procesamiento."],"c":0,"e":"Entre las opciones dadas, ASP y PHP son los lenguajes de programación del lado del servidor más utilizados y destacados para el desarrollo web dinámico.","d":2,"id":"q029","unit":"UF2405-UD1"},{"q":"Un objeto es una...","o":["Un estado y una identidad propia.","Un comportamiento.","Una entidad.","Una entidad que tiene un estado, un comportamiento y una identidad propia."],"h":["Concepto fundamental de la Programación Orientada a Objetos (POO).","Representa algo del mundo real (físico o abstracto).","Combina datos (atributos) y funciones (métodos)."],"c":3,"e":"Definimos un objeto como una entidad que tiene un estado, un comportamiento y una identidad propios.","d":1,"id":"q030","unit":"UF2405-UD1"},{"q":"¿Qué es UML?","o":["Un lenguaje de programación estructurado.","Un conjunto de especificaciones que indican cómo construir unos diagramas que sirven para intercambiar información.","Una metodología de desarrollo orientada a objetos.","Un ciclo de vida de desarrollo del software."],"h":["Sus siglas significan Lenguaje de Modelado Unificado.","Es un estándar de modelado visual, no un proceso de desarrollo en sí mismo.","Lo gestiona el Object Management Group (OMG)."],"c":1,"e":"UML es un lenguaje de modelado visual estándar destinado a describir, especificar, diseñar y documentar procesos de negocio y sistemas de software. No es una metodología ni un ciclo de vida, sino un conjunto de especificaciones para diagramas.","d":1,"id":"q031","unit":"UF2406-UD3"},{"q":"Los diagramas de comportamiento en UML:","o":["Muestran el comportamiento dinámico de las clases del sistema.","Muestran cómo se desarrolla un determinado caso de uso.","Muestran el comportamiento dinámico de los objetos del sistema.","Ninguna de las anteriores."],"h":["Se contraponen a los diagramas de estructura.","Describen una serie de cambios en el sistema a lo largo del tiempo.","Ejemplos incluyen diagramas de actividad, de secuencia y de casos de uso."],"c":2,"e":"Los diagramas de comportamiento muestran el comportamiento dinámico de los objetos en un sistema, que puede ser descrito como una serie de cambios en el sistema a lo largo del tiempo.","d":2,"id":"q032","unit":"UF2406-UD3"},{"q":"Una clase abstracta en UML se define como:","o":["Una clase de la que no pueden heredar otras.","Una clase con solo un objeto asociado.","Una clase de la que no se pueden crear objetos.","Ninguna es correcta."],"h":["Existe solo para que otras clases hereden de ella.","Su nombre suele representarse en cursiva en los diagramas.","No tiene instanciación directa."],"c":2,"e":"Una clase abstracta se define como una clase que no se puede instanciar (crear objetos) directamente. Existe para que otras clases hereden de ella y apoyen la reutilización de características.","d":2,"id":"q033","unit":"UF2406-UD3"},{"q":"En UML, la visibilidad de los elementos puede ser:","o":["Pública, de paquete, protegida y privada.","Pública, protegida y privada.","Se usa solamente en clases.","Se indica solo en atributos y métodos."],"h":["Se representa con símbolos como +, ~, #, -.","Permite restringir el uso de un elemento llamado.","Aplica a clases, paquetes, generalizaciones, etc."],"c":0,"e":"UML cuenta con cuatro tipos de visibilidad: pública (+), de paquete (~), protegida (#) y privada (-), que permiten restringir el acceso a los elementos.","d":1,"id":"q034","unit":"UF2406-UD3"},{"q":"Un actor en un diagrama de casos de uso:","o":["Es parte del sistema software modelado.","Representa un elemento externo al sistema.","Solamente se indica mediante un \"hombre de palo\".","Ninguna de las respuestas es correcta."],"h":["Interactúa con el escenario o sistema.","Puede ser un usuario humano, otro sistema o hardware.","Desempeña un rol específico frente al sistema."],"c":1,"e":"Un actor es un clasificador con comportamiento que especifica un papel desempeñado por una entidad externa que interactúa con el escenario (sistema).","d":1,"id":"q035","unit":"UF2406-UD3"},{"q":"En Java, un contenedor de AWT:","o":["Solo puede albergar componentes y no contenedores.","Es a su vez un componente.","Sirve de almacén exclusivo de botones.","Se almacena en una clase JComponente."],"h":["La estructura básica de la librería gira en torno a componentes y contenedores.","Los eventos pueden tratarse tanto en contenedores como en componentes.","Ejemplos son Frame, Panel y Window."],"c":1,"e":"Los contenedores albergan componentes y son componentes a su vez, de forma que los eventos pueden tratarse tanto en contenedores como en componentes.","d":2,"id":"q036","unit":"UF2406-UD4"},{"q":"Según las \"reglas de oro\" de Mantel para el diseño de interfaces, una de ellas es:","o":["Dar el control al usuario.","Utilizar ventanas deslizantes siempre que se pueda.","Todos los botones deben llevar Icono.","Siempre hay que incluir una ayuda on-line."],"h":["Busca reducir la frustración del usuario.","Permite interacción flexible y deshacer acciones.","Las otras dos reglas son reducir la carga de memoria y presentar la información de manera consistente."],"c":0,"e":"Las tres reglas de oro de Mantel son: Dar el control al usuario, Reducir la carga de memoria del usuario, y La información debe desglosarse de manera progresiva (interfaz consistente).","d":2,"id":"q037","unit":"UF2406-UD4"},{"q":"El tiempo de respuesta en una interfaz de usuario:","o":["Lo importante es que su duración sea mínima.","Se caracteriza por dos valores, su duración y su variabilidad.","Ha de tratarse de minimizar su media ponderada.","Ninguna de las respuestas es correcta."],"h":["Si es muy largo, frustra al usuario.","Si es demasiado corto, puede precipitar errores.","Una variabilidad baja permite mantener un ritmo de trabajo constante."],"c":1,"e":"El tiempo de respuesta está caracterizado por dos valores: su duración (media) y su variabilidad (varianza). Una variabilidad baja permite al usuario mantener un ritmo de trabajo constante.","d":2,"id":"q038","unit":"UF2406-UD4"},{"q":"Cuando se produce un evento en la programación guiada por eventos de Java:","o":["Se llama al método \"actionPerformed\" de los oyentes registrados.","El programador debe detectarlos con un esquema if manual.","Se generan tres objetos asociados: el oyente, el evento y la interrupción.","Se recibe un parámetro en el programa principal."],"h":["El modelo de eventos de Java se basa en la delegación.","Un objeto fuente notifica a un objeto oyente.","El oyente implementa una interfaz como ActionListener."],"c":0,"e":"Cada vez que se produce una acción (evento), se genera un objeto de evento (ej. ActionEvent) y se pasa al método correspondiente del listener (oyente) registrado, el cual ejecuta el código dispuesto para ese evento.","d":2,"id":"q039","unit":"UF2406-UD4"},{"q":"Son métodos de la clase TextArea en Java:","o":["getText y setText.","getManyValues y getProportions.","deleteWindows y setWindowsDefault.","Ninguno de los anteriores."],"h":["TextArea proporciona un área para mantener varias líneas de texto.","Permite obtener el contenido actual.","Permite establecer o cambiar el contenido del área de texto."],"c":0,"e":"Los métodos más utilizados de TextArea son getText() para devolver el texto en el área y setText(String s) para establecer o modificar el texto.","d":1,"id":"q040","unit":"UF2406-UD4"},{"q":"La arquitectura Cliente/Servidor básica (de dos capas) se compone de:","o":["Cliente y servidor.","Cliente, servidor de aplicaciones y servidor de datos.","Servidor de aplicación y servidor de datos.","Ninguna de las anteriores es correcta."],"h":["Es la estructura más simple de red.","El cliente solicita y el servidor responde.","No incluye una capa intermedia de lógica de negocio separada físicamente."],"c":0,"e":"La arquitectura Cliente/Servidor genérica o básica se compone solo del Cliente y del Servidor, recibiendo el nombre de arquitectura de dos niveles o dos capas.","d":1,"id":"q041","unit":"UF2405-UD2"},{"q":"Una arquitectura n_capas se compone de:","o":["Cliente, servidor de aplicaciones, servidor de datos.","Cliente y servidor de aplicación.","Cliente, servidor de aplicación, servidor de datos y otros servidores capaces de dar servicios.","Servidor de aplicación, servidor de datos."],"h":["Es una evolución de la arquitectura de tres capas.","Puede incluir servidores adicionales según las necesidades del negocio.","Ejemplos de servidores adicionales: chat, correo electrónico, etc."],"c":2,"e":"La arquitectura n_capas, además de componerse del Cliente, Servidor de aplicación y Servidor de datos, puede llevar otro u otros tipos más de servidores especializados.","d":2,"id":"q042","unit":"UF2405-UD2"},{"q":"¿Qué permite el Middleware en un sistema distribuido?","o":["Permitir la comunicación entre las aplicaciones que están repartidas por una red de ordenadores.","Nunca permitirá la comunicación entre las aplicaciones.","A veces permitirá la comunicación.","Ninguna de las anteriores es correcta."],"h":["Actúa como conductor o intermediario entre sistemas.","Se ejecuta en ambas partes (cliente y servidor).","Evita el uso de tecnologías propietarias para la interconexión."],"c":0,"e":"El middleware actuará como conductor entre sistemas permitiendo que cualquier usuario pueda comunicarse con varias fuentes de información conectadas por una red, siendo el intermediario transparente entre el cliente y el servidor.","d":2,"id":"q043","unit":"UF2405-UD2"},{"q":"El concepto de n-Tier se refiere a:","o":["El número de capas lógicas.","El número de capas lógicas y físicas.","El número de capas y la distribución física de estas.","El número de capas."],"h":["Se contrapone a n-layer (que es solo la organización lógica del código).","Define dónde suceden los procesos físicamente.","Está relacionado con la distribución en diferentes ordenadores o servidores."],"c":2,"e":"El n_Tier es el número de capas y la distribución física de estas, es decir, dónde suceden los procesos y se encuentra el código físicamente en la red.","d":3,"id":"q044","unit":"UF2405-UD2"},{"q":"La estructura lógica del modelo multicapa (de tres capas) se divide en:","o":["Capa de presentación y capa de aplicación o de negocio.","Capa de aplicación o de negocio.","Capa de presentación, capa de aplicación o de negocio y capa de gestión de datos.","Capa de presentación y capa de gestión de datos."],"h":["La primera interactúa con el usuario.","La segunda contiene la lógica y reglas del negocio.","La tercera se encarga del almacenamiento y acceso a los datos."],"c":2,"e":"La estructura lógica de este modelo se divide en tres: Capa de gestión de datos, Capa de aplicación o de negocio, y La capa de Presentación.","d":1,"id":"q045","unit":"UF2405-UD2"},{"q":"¿A qué capa corresponderá la función de almacenamiento de datos?","o":["A la capa de gestión de datos.","A la capa de presentación.","A la capa de aplicación o de negocio.","A la capa de presentación y a la de aplicación o de negocio."],"h":["Es la capa más baja en la jerarquía de tres capas.","Utiliza sistemas gestores de bases de datos como SQL Server u Oracle.","Suministra los datos solicitados por el servidor de aplicación."],"c":0,"e":"La capa de datos (o gestión de datos) corresponderá al almacenamiento de los datos y al acceso a ellos, siendo responsable del tratamiento de gestión y almacenamiento.","d":1,"id":"q046","unit":"UF2405-UD2"},{"q":"¿Qué patrón arquitectónico se utiliza para unificar las aplicaciones web separando la interfaz gráfica del código?","o":["VCA.","MVC.","NCV.","CML."],"h":["Sus siglas significan Modelo-Vista-Controlador.","El Controlador recibe las peticiones del usuario.","El Modelo gestiona la lógica de negocio y los datos."],"c":1,"e":"Para unificar las aplicaciones web se utiliza un patrón arquitectónico llamado Modelo Vista Controlador (MVC), que separa la interfaz gráfica (Vista) del código de programación (Controlador y Modelo).","d":2,"id":"q047","unit":"UF2405-UD2"},{"q":"Una aplicación distribuida está formada por componentes que se dividen según:","o":["Sea del lado del servidor.","Sea del lado del Cliente.","Sea del lado del cliente o del lado del servidor.","Las tres anteriores son correctas (en conjunto definen la división)."],"h":["El lado del cliente realiza las peticiones (ej. navegador).","El lado del servidor espera y responde a las peticiones.","La división abarca ambos lados por definición."],"c":3,"e":"Una aplicación distribuida está formada por un conjunto de distintos componentes que se dividirán según sea del Lado del Cliente o del Lado del servidor, por lo que las opciones que mencionan estos lados son correctas en su conjunto.","d":2,"id":"q048","unit":"UF2405-UD2"},{"q":"¿Cuál será el objetivo principal de separar la capa lógica o de negocio?","o":["Ahorro económico.","Ahorro energético.","Perder flexibilidad.","Ganar flexibilidad."],"h":["Permite almacenar físicamente la capa de negocios de forma independiente.","Facilita la reutilización de la lógica desde distintas capas de presentación.","Permite modificar la capa de datos sin afectar a la presentación."],"c":3,"e":"Separando en capas lógicas la aplicación, se conseguirá flexibilidad a la hora de almacenar físicamente la capa de negocios, ejecutarla en un servidor centralizado y modificarla sin afectar a las otras capas.","d":2,"id":"q049","unit":"UF2405-UD2"},{"q":"Los motores de reglas de negocio son:","o":["Un conjunto de peticiones, reglas y normas del negocio.","Un conjunto de componentes que a partir de un conjunto de reglas detectará cuáles deben de utilizarse.","Un conjunto de reglas.","Un conjunto de reglas y estándares."],"h":["Forman parte de la capa de negocio.","Evalúan condiciones dinámicamente.","Determinan el resultado de aplicar dichas reglas."],"c":1,"e":"Los motores de reglas de negocio son componentes que, a partir de un conjunto de reglas, detectarán qué reglas deberán de utilizarse y cuál será el resultado de aplicarlas.","d":2,"id":"q050","unit":"UF2405-UD2"},{"q":"La arquitectura Cliente/Servidor básica se compone de:","o":["Cliente y servidor.","Cliente, servidor de aplicaciones y servidor de datos.","Servidor de aplicación y servidor de datos.","Ninguna de las anteriores es correcta."],"h":["Es el modelo de red más simple.","No incluye capas intermedias de lógica de negocio separada físicamente.","Consta únicamente de quien pide la información y quien la responde."],"c":0,"e":"La arquitectura Cliente/Servidor genérica o básica se compone únicamente del Cliente y del Servidor, recibiendo el nombre de arquitectura de dos niveles o dos capas.","d":1,"id":"q051","unit":"UF2405-UD2"},{"q":"¿Qué permitirá el Middleware?","o":["Permitirán la comunicación entre las aplicaciones que están repartidas por una red de ordenadores.","Nunca permitirán la comunicación entre las aplicaciones.","A veces permitirán la comunicación.","Ninguna de las anteriores es correcta."],"h":["Actúa como conductor o intermediario entre sistemas.","Se ejecuta en ambas partes (cliente y servidor).","Evita el uso de tecnologías propietarias para la interconexión."],"c":0,"e":"El middleware actuará como conductor entre sistemas permitiendo que cualquier usuario pueda comunicarse con varias fuentes de información conectadas por una red, siendo el intermediario transparente.","d":2,"id":"q052","unit":"UF2405-UD2"},{"q":"La estructura lógica del modelo multicapa se divide en:","o":["Capa de presentación y capa de aplicación o de negocio.","Capa de aplicación o de negocio.","Capa de presentación, capa de aplicación o de negocio y capa de gestión de datos.","Capa de presentación y capa de gestión de datos."],"h":["La primera interactúa con el usuario.","La segunda contiene la lógica y reglas del negocio.","La tercera se encarga del almacenamiento y acceso a los datos."],"c":2,"e":"La estructura lógica de este modelo se divide en tres: Capa de gestión de datos, Capa de aplicación o de negocio, y La capa de Presentación.","d":1,"id":"q053","unit":"UF2405-UD2"},{"q":"Una aplicación distribuida está formada por componentes que se dividen según:","o":["Sea del lado del servidor.","Sea del lado del Cliente.","Sea del lado del cliente o del lado del servidor.","Las tres anteriores son correctas."],"h":["El lado del cliente realiza las peticiones (ej. navegador).","El lado del servidor espera y responde a las peticiones.","La división abarca ambos lados por definición."],"c":3,"e":"Una aplicación distribuida está formada por un conjunto de distintos componentes que se dividirán según sea del Lado del Cliente o del Lado del servidor, por lo que las opciones que mencionan estos lados son correctas en su conjunto.","d":2,"id":"q054","unit":"UF2405-UD2"},{"q":"La base de toda interfaz de usuario es:","o":["Lenguaje ASP.","Lenguaje de marcado HTML.","Lenguaje XML.","Lenguaje C++."],"h":["Es un lenguaje de hipertexto.","Está formado por un conjunto de etiquetas.","Define la estructura y el contenido de una página web."],"c":1,"e":"El fundamento del interfaz de un usuario de una aplicación Web es el Lenguaje HTML (HyperText Markup Language), un lenguaje de marcado derivado de XML.","d":1,"id":"q055","unit":"UF2405-UD3"},{"q":"Los componentes que forman la capa de presentación se dividen en:","o":["Componentes de aplicación.","Componentes de aplicación y componentes de desarrollo.","Componentes de presentación y componentes de procesos.","Componentes de procesos y componentes de desarrollo."],"h":["Unos permiten al usuario interactuar directamente (botones, etiquetas).","Otros se utilizan para interacciones más complejas (frameworks de JavaScript).","Ambos conforman la interfaz visible."],"c":2,"e":"Los componentes que conforman la capa de presentación se dividen en dos: Componentes de presentación (interfaz para interactuar) y Componentes de procesos (para interacciones complejas).","d":1,"id":"q056","unit":"UF2405-UD3"},{"q":"Los lenguajes del lado del cliente corresponderán a:","o":["Los lenguajes que tendrán que transformar los datos para que lo entiendan el navegador web.","Los lenguajes que tendrán que transformar los datos para que lo entiendan el servidor de datos.","Los lenguajes que no tendrán que transformar los datos para que lo entiendan el navegador web.","Los lenguajes que tendrán que transformar los datos para que lo entiendan el servidor de aplicaciones."],"h":["Se ejecutan directamente en el navegador.","No requieren pre- tratamiento en el servidor.","Ejemplos: HTML, JavaScript, CSS."],"c":2,"e":"Los lenguajes del lado del Cliente corresponderán a los lenguajes que no tendrán que transformar los datos para que sean entendibles por el navegador, ya que se realizarán en HTML y no tendrán que ser pre-tratados.","d":2,"id":"q057","unit":"UF2405-UD3"},{"q":"Un Script es...","o":["Un pequeño programa que suele estar fuera del contenido HTML.","Un pequeño programa que suele estar dentro del contenido HTML.","Un pequeño programa que suele estar fuera y fuera del contenido HTML.","No es un programa."],"h":["Se carga cuando se ejecuta la página.","Responde a eventos del usuario.","Aporta dinamismo al documento."],"c":1,"e":"Un script se trata de un programa que suele estar dentro del contenido de HTML. Cuando se ejecuta, se cargarán todas las instrucciones de dicho programa, a esta acción se le denomina evento.","d":1,"id":"q058","unit":"UF2405-UD3"},{"q":"¿Qué es Java Script?","o":["Un lenguaje interpretado.","Un lenguaje orientado a objetos.","Un lenguaje no compilado.","A y b son correctas."],"h":["No necesita un compilador externo, el navegador lo interpreta.","Se basa en objetos para estructurar el código.","Se embebe directamente en el HTML."],"c":3,"e":"JavaScript es un lenguaje de programación orientado a objetos e interpretado, con lo que no necesitará la ayuda de compiladores, siendo el más utilizado como lenguaje de programación del lado del cliente.","d":2,"id":"q059","unit":"UF2405-UD3"},{"q":"Con Java Script se podrá crear:","o":["Efectos especiales para crear contenidos estáticos.","Efectos especiales para crear contenidos dinámicos.","Efectos especiales para crear contenidos dinámicos y dar movimiento a los componentes de la página web.","Efectos especiales para crear contenidos estáticos y dar movimiento a los componentes de la página web."],"h":["Permite validar formularios antes de enviarlos.","Puede modificar el DOM en tiempo real.","Aporta interactividad y movimiento."],"c":2,"e":"Con JavaScript se podrá realizar efectos para poder crear contenidos más dinámicos y también se podrá dar movimiento a los componentes de la página web.","d":2,"id":"q060","unit":"UF2405-UD3"},{"q":"Visual Basic Script solo es compatible con:","o":["Internet Explorer.","Mozilla Firefox.","Opera.","Google Chrome."],"h":["Es una versión reducida de Visual Basic.","Fue desarrollado por Microsoft.","Otros navegadores modernos no lo soportan de forma nativa."],"c":0,"e":"VBScript es una versión reducida del lenguaje de programación Visual Basic, desarrollada por Microsoft, y solo es compatible de forma nativa con Internet Explorer.","d":1,"id":"q061","unit":"UF2405-UD3"},{"q":"¿Qué significa CSS?","o":["Hoja de estilo.","Cascada.","Hoja de estilo en cascada.","Ninguna de las anteriores."],"h":["Sus siglas en inglés son Cascading Style Sheets.","Se ocupa de las características gráficas de un documento HTML.","Permite separar el contenido del diseño."],"c":2,"e":"CSS significa Hoja de Estilo en Cascada (Cascading Style Sheets). Este tipo de lenguaje se ocupa de las características gráficas que se les puede aplicar a los elementos de un documento HTML.","d":1,"id":"q062","unit":"UF2405-UD3"},{"q":"¿Cuáles son los lenguajes más utilizados del lado del servidor?","o":["CGI, PERL, ASP.","PHP, DHTML, XML.","ASP, PHP, PERL.","ASP, PHP, JSP y Servlets."],"h":["Se procesan en el servidor antes de enviar la respuesta al cliente.","Generan contenido dinámico.","Incluyen tecnologías Java y de Microsoft."],"c":3,"e":"Los lenguajes de programación más utilizados en el desarrollo de aplicaciones web del lado del servidor son principalmente: ASP, PHP, JSP y Servlets (además de HTML y JavaScript en ciertos contextos mixtos).","d":2,"id":"q063","unit":"UF2405-UD3"},{"q":"PHP es un lenguaje de:","o":["Uso libre y gratuito.","Uso libre y de pago.","Uso libre de pago o gratuito.","Uso libre."],"h":["Sus siglas significan HyperText Preprocessor.","Es de código abierto.","Se incrusta en el código HTML."],"c":0,"e":"PHP es un lenguaje muy conocido popularmente por ser un lenguaje de código abierto, esto quiere decir que es libre de uso y gratuito, y para el desarrollo de páginas web dinámicas.","d":1,"id":"q064","unit":"UF2405-UD3"},{"q":"UML es:","o":["Un lenguaje de programación estructurado.","Un conjunto de especificaciones que indican cómo construir unos diagramas que sirve para intercambiar información.","Una metodología de desarrollo orientada a objetos.","Un ciclo de vida de desarrollo del software."],"h":["Sus siglas significan Lenguaje de Modelado Unificado.","Es un estándar de modelado visual, no un proceso de desarrollo en sí mismo.","Lo gestiona el Object Management Group (OMG)."],"c":1,"e":"UML es un lenguaje de modelado visual estándar destinado a ser utilizado para el modelado de procesos de negocio y similares, análisis, diseño e implementación de sistemas basados en software. Es un conjunto de especificaciones para diagramas.","d":1,"id":"q065","unit":"UF2406-UD3"},{"q":"Los diagramas de comportamiento:","o":["Muestran el comportamiento dinámico de las clases del sistema.","Muestran cómo se desarrolla un determinado caso de uso.","Muestran el comportamiento dinámico de los objetos del sistema.","Ninguna de las anteriores."],"h":["Se contraponen a los diagramas de estructura.","Describen una serie de cambios en el sistema a lo largo del tiempo.","Ejemplos incluyen diagramas de actividad, de secuencia y de casos de uso."],"c":2,"e":"Los diagramas de comportamiento muestran el comportamiento dinámico de los objetos en un sistema, que puede ser descrito como una serie de cambios en el sistema a lo largo del tiempo.","d":2,"id":"q066","unit":"UF2406-UD3"},{"q":"El diagrama de clases:","o":["Es un diagrama que muestra la estructura del sistema diseñado en el nivel de las clases y las interfaces.","Es un diagrama que muestra los objetos del sistema.","Muestra el comportamiento de un sistema.","Se ajusta a la normativa ISO."],"h":["Es un diagrama de estructura.","Muestra características, limitaciones y relaciones (asociaciones, generalizaciones, dependencias).","Es el más utilizado en el diseño orientado a objetos."],"c":0,"e":"El diagrama de clases es un diagrama UML de estructura que muestra la estructura del sistema diseñado en el nivel de las clases y las interfaces, muestra sus características, estructura y relaciones.","d":1,"id":"q067","unit":"UF2406-UD3"},{"q":"Una clase abstracta:","o":["Es una clase de la que no pueden heredar otras.","Es una clase con solo un objeto asociado.","Es una clase de la que no se pueden crear objetos.","Ninguna es correcta."],"h":["Existe solo para que otras clases hereden de ella.","Su nombre suele representarse en cursiva en los diagramas.","No tiene instanciación directa."],"c":2,"e":"Una clase abstracta se define como una clase que no se puede instanciar (crear objetos) directamente. Existe para que otras clases hereden de ella y apoyen la reutilización de características.","d":2,"id":"q068","unit":"UF2406-UD3"},{"q":"Una operación:","o":["Especifica nombre, tipo, parámetro y restricciones.","Especifica nombre, tipo y parámetros.","Especifica un nombre.","Especifica parámetros in y parámetros out."],"h":["Es una característica del comportamiento de un clasificador.","Se invoca en una instancia del clasificador.","Puede tener efectos secundarios o ser una consulta."],"c":0,"e":"Una operación es una característica del comportamiento de un clasificador que especifica el nombre, tipo, parámetros y limitaciones (restricciones) para invocar un comportamiento asociado.","d":2,"id":"q069","unit":"UF2406-UD3"},{"q":"La visibilidad en UML:","o":["Puede ser pública, de paquete, protegida y privada.","Puede ser pública, protegida y privada.","Se usa solamente en clases.","Se indica en atributos y métodos."],"h":["Se representa con símbolos como +, ~, #, -.","Permite restringir el uso de un elemento llamado.","Aplica a clases, paquetes, generalizaciones, etc."],"c":0,"e":"UML cuenta con los siguientes tipos de visibilidad: pública (+), de paquete (~), protegida (#) y privada (-), que permiten restringir el acceso a los elementos.","d":1,"id":"q070","unit":"UF2406-UD3"},{"q":"Una asociación:","o":["Es una relación entre clasificadores.","Es una relación entre clases.","Es una relación entre objetos.","Es una relación entre casos de uso."],"h":["Muestra que los casos de los clasificadores pueden estar vinculados entre sí.","Puede ser lógica o física.","Se dibuja generalmente como una línea continua."],"c":0,"e":"La asociación es una relación entre clasificadores que se utilizan para mostrar que los casos de los clasificadores pueden ser ya sea vinculados entre sí o combinada lógica o físicamente en alguna agregación.","d":2,"id":"q071","unit":"UF2406-UD3"},{"q":"Un actor en un caso de uso:","o":["Es parte del sistema software modelado.","Representa un elemento externo al sistema.","Solamente se indica mediante un \"hombre de palo\".","Ninguna de las respuestas es correcta."],"h":["Interactúa con el escenario o sistema.","Puede ser un usuario humano, otro sistema o hardware.","Desempeña un rol específico frente al sistema."],"c":1,"e":"Un actor es un clasificador con comportamiento que especifica un papel desempeñado por una entidad externa que interactúa con el escenario (sistema).","d":1,"id":"q072","unit":"UF2406-UD3"},{"q":"Un diagrama de actividad:","o":["Representa la actividad de un actor en el sistema.","Es un diagrama estático.","Es un diagrama de comportamiento.","Modelan la organización a nivel medio."],"h":["Muestra flujo de control o flujo de objetos.","Hace énfasis en la secuencia y las condiciones del flujo.","Se asemeja a un diagrama de flujo tradicional."],"c":2,"e":"El Diagrama de actividad es un diagrama de comportamiento UML que muestra flujo de control o flujo de objetos con énfasis en la secuencia y las condiciones del flujo.","d":2,"id":"q073","unit":"UF2406-UD3"},{"q":"Un mensaje:","o":["Ha de tener una visibilidad pública o privada dependiendo del tipo de clasificador al que apunte.","Sirve para indicar la creación o finalización de un objeto.","Indica la terminación de dos o más líneas de vida.","Es un elemento que define un tipo específico de comunicación entre dos líneas de vida."],"h":["Específica el emisor y el receptor.","Puede ser síncrono, asíncrono, de creación o de respuesta.","Se muestra como una línea con una punta de flecha."],"c":3,"e":"Un mensaje es un elemento con un nombre que define un tipo específico de la comunicación entre líneas de vida de una interacción.","d":2,"id":"q074","unit":"UF2406-UD3"},{"q":"¿Qué nombre reciben las estructuras y datos proporcionados por un SGBD?","o":["Jerárquica.","Modelo de datos.","Base de datos en red.","Sistema de gestión de base de datos."],"h":["Es el conjunto de herramientas conceptuales para describir las relaciones.","Define la semántica y las condiciones de consistencia de los datos.","Existen modelos lógicos basados en objetos, en registros y físicos."],"c":1,"e":"Las estructuras de datos y el acceso proporcionados por un SGBD reciben el nombre de modelo de datos, siendo el relacional el más utilizado actualmente.","d":1,"id":"q075","unit":"UF2405-UD4"},{"q":"¿En cuántas etapas se divide el diseño de una base de datos?","o":["En dos, etapa de diseño conceptual y etapa diseño lógica.","En dos, etapa diseño conceptual y etapa diseño físico.","En tres, etapa conceptual, etapa física y etapa de diseño abstracto.","En tres, etapa conceptual, etapa lógica y etapa diseño físico."],"h":["La primera configura la estructura independientemente de la tecnología.","La segunda transforma el modelo Entidad-Relación a relacional.","La tercera se refiere a los aspectos físicos de implementación en memoria."],"c":3,"e":"El diseño de una base de datos se divide en tres etapas: diseño conceptual (modelo E-R), diseño lógico (modelo relacional) y diseño físico (implementación en memoria secundaria).","d":2,"id":"q076","unit":"UF2405-UD4"},{"q":"¿Qué es una entidad en el modelo Entidad-Relación?","o":["Son las características o propiedades que pueden definir un atributo.","Es la representación de un objeto en el mundo real, que se puede distinguir del resto.","Es la unión entre atributos.","Ninguna de las anteriores es correcta."],"h":["Puede ser algo tangible (como un alumno) o intangible (como una asignatura).","Se representa gráficamente con un rectángulo.","Posee atributos que la describen."],"c":1,"e":"Una entidad es la representación de un objeto del mundo real, distinguible de otros objetos, que se describe mediante un conjunto de atributos.","d":1,"id":"q077","unit":"UF2405-UD4"},{"q":"Un atributo se representa gráficamente con un...","o":["Rombo.","Elipse.","Línea.","Cuadrado."],"h":["Representa las características o propiedades de una entidad.","Se une mediante un guion al rectángulo de la entidad.","Su nombre se escribe en minúsculas dentro de la figura."],"c":1,"e":"En el diagrama Entidad-Relación, los atributos se representan físicamente mediante una elipse con su nombre en minúsculas, unida a la entidad correspondiente.","d":1,"id":"q078","unit":"UF2405-UD4"},{"q":"Para que una entidad sea distinguible del resto será necesario tener un atributo o varios que la identifiquen, estos atributos recibirán el nombre de...","o":["Clave ajena.","Clave foránea.","Clave ajena o foránea.","Clave primaria."],"h":["Garantiza la integridad de la entidad.","No puede contener valores nulos.","Identifica de forma única cada fila o tupla de la tabla."],"c":3,"e":"La clave primaria es el atributo (o conjunto de atributos) que identifica de forma única a cada ocurrencia de una entidad, diferenciándola del resto.","d":2,"id":"q079","unit":"UF2405-UD4"},{"q":"¿Qué significa la cardinalidad de una relación?","o":["Es el tipo de correspondencia que se establecerá entre las entidades de la relación, reflejando el número de ocurrencias.","Es el tipo de correspondencia entre los atributos de la relación.","Es el tipo de correspondencia que no refleja el número de ocurrencias.","Es el tipo de correspondencia que no se establecerá entre las entidades."],"h":["Define cuántas instancias de una entidad se relacionan con otra.","Puede ser 1:1, 1:N o M:N.","Se indica en los extremos de la línea de relación en el diagrama."],"c":0,"e":"La cardinalidad es el tipo de correspondencia que se establece entre las entidades de una relación, reflejando el número de ocurrencias de una entidad con las ocurrencias de la otra.","d":2,"id":"q080","unit":"UF2405-UD4"},{"q":"¿Qué tres operaciones fundamentales del álgebra relacional permitirán la creación de nuevas tablas a partir de las ya existentes?","o":["Diseño lógico, diseño conceptual y diseño físico.","Selección, proyección y concatenación o unión.","Lógica, proyección y concatenación.","Selección, lógica y concatenación."],"h":["Una filtra filas según una condición.","Otra filtra columnas específicas.","La tercera combina registros de dos tablas."],"c":1,"e":"Las operaciones fundamentales del álgebra relacional en las que se basa SQL son: Selección (filas), Proyección (columnas) y Concatenación o Unión (combinación de tablas).","d":2,"id":"q081","unit":"UF2405-UD4"},{"q":"¿Cuáles son los tipos de lenguajes utilizados en un SGBD según las operaciones que realizan?","o":["Lenguajes de control de datos DCL.","Lenguajes de definición de datos DDL.","Lenguaje de manipulación de datos DML.","A, b y c son correctas."],"h":["Uno define la estructura (CREATE, ALTER).","Otro manipula los datos (SELECT, INSERT).","Otro controla los permisos y accesos (GRANT, REVOKE)."],"c":3,"e":"Los lenguajes de un SGBD se clasifican en DDL (Definición de Datos), DML (Manipulación de Datos) y DCL (Control de Datos), entre otros como TCL.","d":1,"id":"q082","unit":"UF2405-UD4"},{"q":"SQL es un lenguaje...","o":["Es un lenguaje no declarativo.","Es un lenguaje declarativo.","Es un lenguaje declarativo y no procedimental.","Es un lenguaje declarativo y procedimental."],"h":["El usuario describe QUÉ quiere obtener, no CÓMO obtenerlo.","No se basa en algoritmos paso a paso.","Está estandarizado por ANSI/ISO."],"c":2,"e":"SQL es un lenguaje declarativo y no procedimental, lo que significa que se basa en describir las condiciones y restricciones de los datos deseados, dejando al SGBD la tarea de determinar cómo ejecutar la consulta.","d":2,"id":"q083","unit":"UF2405-UD4"},{"q":"Las tecnologías más utilizadas para realizar aplicaciones web son:","o":["CGI, ASP, .NET y JSP.",".NET, CGI, JSP, PHP y ASP.",".NET, JSP y PHP.","CGI, JSP y .NET."],"h":["Incluyen lenguajes de script del lado del servidor.","Algunas son de código abierto y otras propietarias.","El texto menciona explícitamente CGI, ASP, .NET, JSP y PHP como el conjunto más utilizado."],"c":1,"e":"Las tecnologías más utilizadas para realizar aplicaciones web incluyen CGI, ASP, .NET, JSP y PHP, cubriendo tanto entornos Microsoft como Java y código abierto.","d":1,"id":"q084","unit":"UF2405-UD5"},{"q":"¿Cuáles son los elementos que forman una base de datos?","o":["El hardware y un software.","El hardware.","El hardware, un software y datos.","Ninguna de las anteriores."],"h":["Necesita dispositivos de almacenamiento físico.","Requiere un SGBD para gestionarla.","Contiene la información estructurada en sí misma."],"c":2,"e":"Una base de datos está compuesta por el hardware (dispositivos de almacenamiento), el software (SGBD) y los datos almacenados de forma estructurada.","d":1,"id":"q085","unit":"UF2405-UD5"},{"q":"¿De qué se ocupa el programador de aplicaciones en el contexto de una base de datos?","o":["Son aquellos que acceden a la información por medio de lenguajes de consulta SQL.","Son aquellos que a través de un lenguaje generan nuevos módulos u objetos capaces de manejar nuevos datos en el sistema.","Son aquellos que utilizan aplicaciones avanzadas para reconocer imágenes.","Son aquellos que interactúan con el SGBD por medio de aplicaciones permanentes."],"h":["Tiene un dominio completo del lenguaje de definición y manipulación.","Crea el software que interactúa con la base de datos.","Desarrolla la lógica de la aplicación."],"c":1,"e":"El programador de aplicaciones es la persona que, mediante un lenguaje de programación, genera módulos u objetos capaces de manejar y procesar los datos del sistema.","d":2,"id":"q086","unit":"UF2405-UD5"},{"q":"La sentencia para conceder permisos de acceso a un usuario es:","o":["GRANT.","SELECT.","REVOKE.","CREATE."],"h":["Pertenece al lenguaje DCL (Data Control Language).","Es el opuesto a denegar o retirar permisos.","Su nombre en inglés significa \"otorgar\"."],"c":0,"e":"La sentencia GRANT se utiliza en SQL para conceder privilegios o permisos de seguridad a un usuario sobre objetos de la base de datos.","d":1,"id":"q087","unit":"UF2405-UD5"},{"q":"¿Cuáles son las operaciones unarias del álgebra relacional?","o":["Unión y diferencia.","Unión, diferencia y producto cartesiano.","Selección y proyección.","Intersección, join y cociente."],"h":["Operan sobre una sola tabla a la vez.","Una filtra filas (tuplas).","La otra filtra columnas (atributos)."],"c":2,"e":"Las operaciones unarias son aquellas que se aplican a una única relación (tabla), siendo la Selección (filtra filas) y la Proyección (filtra columnas) las principales.","d":2,"id":"q088","unit":"UF2405-UD5"},{"q":"La operación de intersección lo que hace es que:","o":["A partir de dos tablas ya existentes dará como resultado una tabla nueva con filas de las dos tablas y columnas de una de ellas.","A partir de dos tablas existentes, se combinan por medio de una condición.","A partir de dos tablas existentes dará como resultado una nueva tabla con las filas que están en una pero no están en la otra.","A partir de dos tablas existentes, dará como resultado una tabla nueva con todas las filas de las dos tablas."],"h":["Es una operación derivada.","Devuelve solo los registros que son comunes a ambas relaciones.","Requiere que las tablas sean compatibles en unión."],"c":0,"e":"La intersección devuelve una tabla nueva que contiene únicamente las filas que existen simultáneamente en ambas tablas originales (y las columnas de una de ellas, al ser compatibles).","d":3,"id":"q089","unit":"UF2405-UD5"},{"q":"Para ejecutar una consulta y obtener datos de una base de datos se utiliza la sentencia:","o":["INSERT.","ALTER.","GRANT.","SELECT."],"h":["Pertenece al lenguaje DQL/DML.","Es la sentencia más compleja y amplia de SQL.","Puede ir acompañada de cláusulas como WHERE, GROUP BY y ORDER BY."],"c":3,"e":"La sentencia SELECT es la instrucción fundamental del lenguaje SQL para recuperar filas o registros de una o varias tablas de una base de datos.","d":1,"id":"q090","unit":"UF2405-UD5"},{"q":"¿Qué determina la cláusula SELECT en una consulta?","o":["Las filas que va a devolver un producto cartesiano.","Las filas que va a devolver una proyección.","Las columnas que va a devolver una consulta.","Las columnas que va a devolver una unión."],"h":["Define la \"lista de selección\".","Puede usar el asterisco (*) para indicar \"todas\".","Determina qué atributos específicos se mostrarán en el resultado."],"c":2,"e":"La cláusula SELECT determina específicamente las columnas (atributos) que van a ser devueltas como resultado de la consulta.","d":1,"id":"q091","unit":"UF2405-UD5"},{"q":"¿Qué tipos de procedimientos almacenados existen en SQL Server?","o":["Del sistema y definidos por el usuario.","Del sistema, definidos por el usuario y extendidos.","Del sistema, definidos por el usuario y remotos.","Del sistema, definidos por el usuario, extendidos y remotos."],"h":["Algunos vienen preinstalados con el SGBD (prefijo sp_).","Otros los crea el desarrollador para tareas específicas.","También existen los que se ejecutan como DLLs externas (xp_) y los que acceden a servidores vinculados."],"c":3,"e":"Existen cuatro tipos principales: procedimientos almacenados del sistema, definidos por el usuario, extendidos (que usan DLLs externas) y remotos (para bases de datos distribuidas).","d":3,"id":"q092","unit":"UF2405-UD5"},{"q":"Una transacción de base de datos es:","o":["Es una unidad de trabajo realizada por una o varias sentencias SQL relacionadas.","Está formada por una serie de instrucciones SQL que definirán un determinado proceso.","Es un programa externo y local.","Es un programa externo."],"h":["Debe cumplir las propiedades ACID.","Se trata de una unidad lógica indivisible.","O se ejecuta por completo o no se ejecuta nada (atomicidad)."],"c":0,"e":"Una transacción es una unidad lógica de trabajo compuesta por una o varias sentencias SQL que deben ejecutarse juntas para mantener la coherencia de los datos.","d":2,"id":"q093","unit":"UF2405-UD5"},{"q":"¿De qué está compuesta una base de datos a nivel lógico?","o":["Por tablas, columnas y tipos de datos.","Por tablas y columnas.","Por tablas.","Ninguna de las anteriores."],"h":["Las tablas son la estructura básica.","Las columnas definen los atributos.","Cada columna tiene un tipo de dato específico que valida la entrada."],"c":0,"e":"Una base de datos relacional está compuesta lógicamente por tablas (relaciones), que a su vez están formadas por columnas (atributos) con tipos de datos definidos.","d":1,"id":"q094","unit":"UF2405-UD6"},{"q":"ANSI recomendó que la estructura de los SGBD tuvieran tres niveles. ¿Cuáles son?","o":["Nivel intermedio, nivel pragmático y nivel interno.","Nivel conceptual, nivel externo y nivel interno o físico.","Esquema conceptual, esquema externo y esquema físico.","B y c son correctas."],"h":["Separa la visión del usuario de la implementación física.","El nivel externo son las vistas de usuario.","El nivel interno es el almacenamiento físico."],"c":3,"e":"ANSI recomendó la arquitectura de tres niveles: conceptual (lógica global), externo (vistas de usuario) e interno o físico (almacenamiento), lo que también se denomina mediante sus esquemas correspondientes.","d":2,"id":"q095","unit":"UF2405-UD6"},{"q":"¿Cuál es el modelo más utilizado y extendido por los desarrolladores para el diseño y análisis de datos?","o":["Entidad.","Entidad-relación.","Relación.","Modelo orientado a objeto."],"h":["Fue propuesto por Peter Chen en los 70.","Utiliza rectángulos, elipses y rombos.","Es la base para luego transformar al modelo relacional."],"c":1,"e":"El modelo Entidad-Relación (E-R) es el más aceptado y extendido para realizar el diseño conceptual y análisis de los datos antes de pasar al modelo relacional.","d":1,"id":"q096","unit":"UF2405-UD6"},{"q":"El lenguaje de definición de datos (DDL) es un lenguaje:","o":["Proporcionado por el SGBD para realizar consultas.","Proporcionado por el SGBD para realizar inserciones.","Proporcionado por el SGBD para realizar borrados.","Proporcionado por el SGBD para permitir que los usuarios creen básicamente estructuras de datos."],"h":["Incluye sentencias como CREATE, ALTER y DROP.","No manipula los datos en sí, sino su contenedor.","Define tablas, vistas, dominios y restricciones."],"c":3,"e":"El DDL (Data Definition Language) es proporcionado por el SGBD y se utiliza específicamente para crear, modificar y eliminar las estructuras de datos (tablas, vistas, etc.), no los datos en sí.","d":1,"id":"q097","unit":"UF2405-UD6"},{"q":"¿Cuáles son las sentencias que componen el lenguaje de definición de datos DDL?","o":["CREATE y ALTER.","CREATE, ALTER y DROP.","CREATE y DROP.","CREATE, ALTER, DROP y TRUNCATE."],"h":["Una crea objetos.","Otra los modifica.","Otras dos eliminan objetos o vacían su contenido por completo."],"c":3,"e":"Las sentencias fundamentales del DDL son CREATE (crear), ALTER (modificar), DROP (eliminar estructura y datos) y TRUNCATE (vaciar datos manteniendo la estructura).","d":1,"id":"q098","unit":"UF2405-UD6"},{"q":"¿Cuál es la modificación estándar que incorporó el estándar ODBC?","o":["CLI-95.","PSM-96.","OLB-98.","SQL 99 o SQL3."],"h":["Es un estándar de SQL/CLI.","Permite acceder desde una aplicación a una base de datos relacional mediante llamadas a funciones.","Sus siglas significan Call Level Interface."],"c":0,"e":"El estándar CLI-95 (Call Level Interface) incorporó y estandarizó las funcionalidades de ODBC para el acceso a bases de datos desde aplicaciones mediante llamadas a funciones.","d":3,"id":"q099","unit":"UF2405-UD6"},{"q":"La sentencia CREATE permitirá la creación de:","o":["Tablas, columnas y restricciones.","Tablas, dominios, restricciones y procedimientos.","Dominios y restricciones.","Tablas, dominios y procedimientos."],"h":["Es la sentencia fundamental de creación del DDL.","Puede crear estructuras de datos como tablas.","También puede crear objetos de lógica como procedimientos almacenados."],"c":1,"e":"La sentencia CREATE es versátil y permite la creación de diversos objetos de la base de datos, incluyendo tablas, vistas, dominios, restricciones y procedimientos almacenados.","d":2,"id":"q100","unit":"UF2405-UD6"},{"q":"¿Qué hace la restricción de integridad de columna por defecto DEFAULT?","o":["Asignar un valor a la columna en función del resultado de la expresión.","No se le asignará ningún valor a la columna.","Asignar el valor de una columna que hace referencia a otra tabla.","Asignar un valor por defecto a una columna asignándole un valor al crearla."],"h":["Se utiliza cuando no se proporciona un valor explícito en un INSERT.","Evita que la columna quede vacía si no se especifica lo contrario.","Se define en la creación de la tabla."],"c":3,"e":"La restricción DEFAULT asigna un valor predeterminado a una columna cuando se crea un nuevo registro y no se especifica un valor para esa columna en la instrucción de inserción.","d":1,"id":"q101","unit":"UF2405-UD6"},{"q":"¿Qué es una vista en una base de datos?","o":["Es un procedimiento almacenado.","Es una tabla derivada de otras tablas, se trata de una tabla virtual, no tiene ninguna correspondencia física.","Es una clase especial de procedimiento almacenado.","Es una tabla normal de una base de datos."],"h":["Se define mediante una sentencia SELECT.","No almacena datos por sí misma (salvo vistas materializadas).","Se utiliza para simplificar consultas o restringir el acceso a ciertos datos."],"c":1,"e":"Una vista es una tabla virtual o derivada que se basa en el resultado de una consulta SELECT. No tiene almacenamiento físico propio, sino que muestra datos de tablas base.","d":2,"id":"q102","unit":"UF2405-UD6"},{"q":"Se distinguen dos tipos de trigger o disparadores:","o":["Trigger DCL y UML.","Trigger DML y DCL.","Trigger DML y DDL.","Trigger DDL y DCL."],"h":["Uno se activa con operaciones de manipulación de datos (INSERT, UPDATE, DELETE).","El otro se activa con operaciones de definición de datos (CREATE, ALTER, DROP)."],"c":2,"e":"SQL distingue entre triggers DML (que responden a cambios en los datos) y triggers DDL (que responden a cambios en la estructura de la base de datos).","d":2,"id":"q103","unit":"UF2405-UD6"},{"q":"Un contenedor de AWT (Abstract Window Toolkit) en Java:","o":["Solo puede albergar componentes y no contenedores.","Es a su vez un componente.","Sirve de almacén de botones.","Se almacena en una clase JComponente."],"h":["La estructura básica de la librería gira en torno a componentes y contenedores.","Los eventos pueden tratarse tanto en contenedores como en componentes.","Ejemplos son Frame, Panel y Window."],"c":1,"e":"En la jerarquía de AWT, los contenedores albergan componentes, pero ellos mismos son considerados componentes, lo que permite anidar contenedores dentro de otros contenedores.","d":2,"id":"q104","unit":"UF2406-UD4"},{"q":"¿Qué es una entidad?","o":["Son las características o propiedades que pueden definir un atributo.","Es la representación de un objeto en el mundo real, que se puede distinguir del resto.","Es la unión entre atributos.","Ninguna de las anteriores es correcta."],"h":["Puede ser algo tangible (como un alumno) o intangible (como una asignatura).","Se representa gráficamente con un rectángulo en un diagrama E-R.","Posee atributos que la describen."],"c":1,"e":"Una entidad es la representación de un objeto del mundo real, distinguible de otros objetos, que se describe mediante un conjunto de atributos.","d":1,"id":"q105","unit":"UF2405-UD4"},{"q":"¿Qué es una relación?","o":["La unión entre distintas entidades.","La unión entre dos entidades.","La unión entre tres entidades.","La unión entre una, dos, tres hasta n-arias."],"h":["Se define como la unión o asociación entre entidades.","Se representa físicamente por medio de un rombo.","Junto al rombo se coloca el nombre de la relación en mayúsculas."],"c":0,"e":"Una relación se define como la unión o asociación entre distintas entidades, pudiendo ser binaria, ternaria o n-aria.","d":1,"id":"q106","unit":"UF2405-UD4"},{"q":"¿Qué tres operaciones fundamentales permitirá la creación de nuevas tablas a partir de las ya existentes?","o":["Diseño lógico, diseño conceptual y diseño físico.","Selección, proyección y concatenación o unión.","Lógica, proyección y concatenación.","Selección, lógica y concatenación."],"h":["Una filtra filas según una condición.","Otra filtra columnas específicas.","La tercera combina registros de dos tablas."],"c":1,"e":"Las operaciones fundamentales del álgebra relacional en las que se basa SQL son: Selección, Proyección y Concatenación o unión.","d":2,"id":"q107","unit":"UF2405-UD4"},{"q":"¿Cuáles son los tipos de lenguajes utilizados según las operaciones que realizan?","o":["Lenguajes de control de datos DCL.","Lenguajes de definición de datos DDL.","Lenguaje de manipulación de datos DML.","A, b y c son correctas."],"h":["Uno define la estructura (CREATE, ALTER).","Otro manipula los datos (SELECT, INSERT).","Otro controla los permisos y accesos (GRANT, REVOKE)."],"c":3,"e":"Los lenguajes de un SGBD se clasifican en DDL (Definición de Datos), DML (Manipulación de Datos) y DCL (Control de Datos), entre otros.","d":1,"id":"q108","unit":"UF2405-UD4"},{"q":"Los factores directos de calidad...","o":["Los que el cliente aprecia de un vistazo.","Uno de ellos es la facilidad de uso.","Son los que se pueden medir directamente sobre el producto.","Ninguna de las anteriores es correcta."],"h":["Se contraponen a los factores indirectos.","Ejemplos incluyen tiempo de ejecución o ocupación de memoria.","Se miden sobre el producto desarrollado, no sobre la percepción del usuario."],"c":2,"e":"Los factores directos son aquellos factores que se pueden medir directamente sobre el producto desarrollado, como el tiempo de ejecución o la ocupación de memoria.","d":1,"id":"q109","unit":"UF2406-UD5"},{"q":"La calidad estructural del software...","o":["Se refiere a la infraestructura que lo soporta.","Se refiere a la forma en que cumple los requisitos funcionales.","Se refiere al modo en que este cumple con los requisitos no funcionales.","Sólo se mide a través de las pruebas."],"h":["Se evalúa analizando el código fuente y la arquitectura.","Incluye robustez y mantenimiento.","La calidad funcional se mide con pruebas, esta se mide con análisis estático."],"c":2,"e":"La calidad estructural se refiere al modo en que el software cumple con los requisitos no funcionales (como robustez o mantenibilidad) y cómo se ha producido correctamente a nivel de arquitectura y código.","d":2,"id":"q110","unit":"UF2406-UD5"},{"q":"La mala calidad de una infraestructura de sistema:","o":["Está correlacionada con el alto impacto que tienen las interrupciones debidas a datos dañados y otros factores.","No afecta al coste de mantenimiento.","Sólo se aplica a sistemas embebidos.","No se aplica en sistemas ERP y CRM."],"h":["Puede causar cortes de aplicación y brechas de seguridad.","Afecta gravemente a los centros de aplicaciones empresariales.","Genera sobrecostos y desperdicio de recursos."],"c":0,"e":"La mala calidad de la infraestructura está fuertemente correlacionada con alto impacto que tienen interrupciones en los negocios debido a datos dañados, cortes de aplicación, brechas de seguridad y problemas de rendimiento.","d":2,"id":"q111","unit":"UF2406-UD5"},{"q":"La fiabilidad:","o":["Sólo se aplica en entornos empresariales.","Es esencial en sistemas de alta velocidad de ejecución.","Es un atributo de resistencia y solidez estructural.","Todas las respuestas son incorrectas."],"h":["Mide el nivel de riesgo y probabilidad de fallos potenciales.","También mide los defectos inyectados por modificaciones.","Su meta es reducir el tiempo de inactividad de las aplicaciones."],"c":2,"e":"La fiabilidad es un atributo de resistencia y solidez estructural que mide el nivel de riesgo y la probabilidad de fallos potenciales de las aplicaciones.","d":2,"id":"q112","unit":"UF2406-UD5"},{"q":"La medición de la calidad del software:","o":["Consiste en cuantificar en qué medida un sistema posee características deseables.","Es realizada exclusivamente por los programadores.","Solamente se aplica en sistemas o proyectos de gran envergadura.","Es una medida de los atributos de código adecuados del sistema."],"h":["Se puede realizar a través de medios cualitativos o cuantitativos.","Para cada característica deseable debe haber atributos medibles.","Es un requisito previo para todas las disciplinas de la ingeniería."],"c":0,"e":"La medición de la calidad del software es cuantificar en qué medida un sistema o software posee características deseables, a través de medios cualitativos, cuantitativos o una mezcla de ambos.","d":1,"id":"q113","unit":"UF2406-UD5"},{"q":"El análisis estructural de calidad y la medición...","o":["Se realizan a través del análisis del código, la arquitectura, plataformas de software y esquemas de bases de datos.","Miden únicamente el esquema de la base de datos.","Se realizan siguiendo los principios de fiabilidad y exhaustividad.","Ninguna de las respuestas es correcta."],"h":["Se realiza en relación a los principios y normas que definen la arquitectura conceptual y lógica.","Es distinto del análisis básico de búsqueda de errores locales.","Evalúa atributos estáticos de calidad."],"c":0,"e":"El análisis estructural de calidad y la medición se realiza a través del análisis del código fuente, la arquitectura, plataforma de software y esquemas de bases de datos en relación a los principios y normas que definen la arquitectura.","d":3,"id":"q114","unit":"UF2406-UD5"},{"q":"La mantenibilidad:","o":["Está relacionada con el concepto de deuda técnica.","Ha de medirse solo en los sistemas empotrados.","Se debe cuidar solo si se prevé que el sistema va a fallar a menudo.","Una baja mantenibilidad siempre tiene su origen en la falta de tiempo."],"h":["Incluye conceptos de modularidad, comprensibilidad y reutilización.","Su baja calidad suele ser resultado de miles de violaciones menores de buenas prácticas.","Es una expresión de los costes derivados de la falta de mantenimiento."],"c":0,"e":"La mantenibilidad está estrechamente relacionada con el concepto de deuda técnica, que es una expresión de los costes derivados de la falta de mantenimiento.","d":2,"id":"q115","unit":"UF2406-UD5"},{"q":"¿Qué atributo NO es de los que deberían tener las métricas de software?","o":["Empíricas e intuitivas.","Simples y sencillas de calcular.","Subjetivas y objetivas.","Consistentes en el empleo de unidades y tamaños."],"h":["Deben producir un resultado no ambiguo.","Deben basarse en el modelo de análisis o diseño.","La subjetividad va en contra de la consistencia y objetividad requerida."],"c":2,"e":"Las métricas deben ser consistentes y objetivas (producir un resultado no ambiguo). La subjetividad no es un atributo deseable en una métrica de software.","d":2,"id":"q116","unit":"UF2406-UD5"},{"q":"Las normas ISO 9000:","o":["Determinan como se deben formar a los programadores en un entorno de calidad.","Indican los documentos de calidad que debe generar una organización.","Establecen los requisitos de un sistema de control de calidad.","Indican como deben hacerse las mediciones de calidad del software."],"h":["Son un grupo de estándares internacionales de administración y aseguramiento de calidad.","Son genéricas, no específicas para un producto.","Documentan qué elementos usar para mantener un sistema eficiente."],"c":2,"e":"La serie de normas ISO-9000 establece los requisitos básicos que debe de cumplir un sistema de control que garantice productos o servicios de calidad consistente.","d":1,"id":"q117","unit":"UF2406-UD5"},{"q":"El modelo de madurez del software CMM:","o":["Indica como cumple la normativa ISO una organización.","Detalla las tareas que se tienen que realizar conforme a la calidad.","Sirve de referencia para indicar el estado de I+D de una empresa.","Detalla cinco niveles inclusivos para determinar la madurez del proceso de desarrollo de una organización."],"h":["Sus siglas son Software Capability Maturity Model.","Los niveles son: Inicial, Repetible, Definido, Gestionado y Optimizado.","Para alcanzar un nivel, se deben haber logrado y mantenido todos los anteriores."],"c":3,"e":"En el Modelo de Madurez de la Capacidad del Software (SW-CMM) se detallan áreas clave del proceso agrupadas en cinco niveles inclusivos para determinar el estado de la madurez del proceso de desarrollo.","d":2,"id":"q118","unit":"UF2406-UD5"},{"q":"Sobre las pruebas de integración:","o":["Sólo se usan pruebas de caja blanca.","Un resguardo simula un subprograma subordinado.","Un controlador simula un subprograma subordinado.","Sólo se usan pruebas de caja negra."],"h":["Es una técnica sistemática para construir la estructura del programa.","Detecta errores asociados con la interacción entre módulos.","El controlador simula el módulo superior, no el subordinado."],"c":1,"e":"Los resguardos sirven para reemplazar módulos que están subordinados (es decir, son llamados) al componente que hay que probar durante las pruebas de integración.","d":2,"id":"q119","unit":"UF2406-UD6"},{"q":"Sobre las pruebas de validación:","o":["Sirven para detectar errores de compilación.","La prueba beta se lleva a cabo por clientes en el lugar de desarrollo.","La prueba alfa se lleva a cabo por un cliente en el lugar de desarrollo.","Se prueban exhaustivamente cada clase antes de integrarla."],"h":["Se consigue cuando el software funciona según las expectativas razonables del cliente.","La prueba beta es en el lugar de trabajo del cliente, sin el desarrollador.","La prueba alfa es en el lugar de desarrollo, con el desarrollador como observador."],"c":2,"e":"La prueba alfa se lleva a cabo por un cliente, en el lugar de desarrollo, usando el software de forma natural con el desarrollador como observador del usuario.","d":1,"id":"q120","unit":"UF2406-UD6"},{"q":"Sobre la prueba del camino básico:","o":["Utiliza la complejidad ciclomática.","Es un método de caja negra.","Se han de ejecutar cada ruta del programa dos veces.","Se han de probar la mitad de los nodos predicado al menos."],"h":["Es una técnica de prueba de caja blanca propuesta por Tom McCabe.","Permite obtener una medida de la complejidad lógica de un programa.","Garantiza que se ejecuta por lo menos una vez cada sentencia."],"c":0,"e":"La prueba del camino básico utiliza la complejidad ciclomática, que proporciona una medición cuantitativa de la complejidad lógica y define el número de caminos independientes del conjunto básico.","d":2,"id":"q121","unit":"UF2406-UD6"},{"q":"Sobre las pruebas de bucles:","o":["Se prueba el límite superior del bucle.","Los bucles simples se prueban una vez.","Con los bucles anidados se usa una estrategia diferente que con los bucles simples.","Se prueba el límite inferior del bucle."],"h":["Se centra exclusivamente en la validez de las construcciones de bucles.","Extender el enfoque de bucles simples a anidados aumentaría las pruebas geométricamente.","Se comienza por el bucle más interior manteniendo los externos en valores mínimos."],"c":2,"e":"Con los bucles anidados se usa una estrategia diferente (comenzando por el más interior y manteniendo los externos en valores mínimos) para evitar un número impracticable de pruebas.","d":2,"id":"q122","unit":"UF2406-UD6"},{"q":"La depuración de programas es el proceso por el que:","o":["Se identifican y corrigen errores de programación en dicho programa.","Se identifican fallos en dicho programa.","Se identifican fallos de compilación en dicho programa.","Ninguna respuesta es válida."],"h":["También se le conoce como debugging.","Implica descubrir errores e identificar qué zonas del programa los producen.","Se utiliza un depurador para ejecutar el programa línea a línea o paso a paso."],"c":0,"e":"La depuración de programas es el proceso por el cual se identifican y corrigen errores de programación, descubriendo qué zonas del programa los producen.","d":1,"id":"q123","unit":"UF2406-UD6"},{"q":"Si se tienen varias pruebas JUnit:","o":["Se pueden combinar en un conjunto de pruebas.","Siempre han de ejecutarse manualmente una a una.","JUNIT no permite más de una prueba a la vez.","Siempre se ejecutan en el mismo orden."],"h":["Se utiliza la anotación @RunWith(Suite.class).","Permite ejecutar todas las clases de prueba en esa suite en el orden especificado.","Facilita la organización de pruebas complejas."],"c":0,"e":"Si se tienen varias clases de prueba, se pueden combinar en un conjunto de pruebas (Suite). La ejecución de un conjunto de pruebas ejecutará todas las clases de prueba en esa suite en el orden especificado.","d":2,"id":"q124","unit":"UF2406-UD6"},{"q":"En la ejecución de un caso de pruebas:","o":["Nunca se deben de automatizar su ejecución.","Hay dos métodos, manual y automatizado.","Se puede obviar el formato de JUnit.","Se tienen que indicar si es una prueba de integración."],"h":["Dependiendo de la naturaleza de la prueba, se suele usar una combinación de ambos.","La automatización es útil para pruebas de regresión.","La manual permite detectar errores no previstos por los scripts."],"c":1,"e":"Hay dos métodos utilizados en la ejecución de casos de prueba: manuales y automatizados. Dependiendo de la naturaleza de la prueba, una combinación de ambos suele ser el mejor método.","d":1,"id":"q125","unit":"UF2406-UD6"},{"q":"Idealmente el software:","o":["Debe pasar al menos el 50% de las pruebas.","Debe de satisfacer la mitad de los requisitos.","Debe satisfacer todos los requisitos.","Debe de liberarse cuanto antes para que el usuario detecte los errores lo antes posible."],"h":["Desde el diseño, cada requisito debe abordarse en cada documento único.","La matriz de trazabilidad ayuda a verificar esto.","Si hay celdas vacías en la matriz, un requisito no se ha abordado correctamente."],"c":2,"e":"Idealmente, el software debe satisfacer por completo el conjunto de requisitos. Desde el diseño, cada requisito debe abordarse en cada documento único en el proceso de software.","d":1,"id":"q126","unit":"UF2406-UD6"},{"q":"El estándar IEEE 829-2008:","o":["Especifica como realizar las pruebas de software.","Especifica como realizar pruebas de caja blanca.","Especifica como realizar pruebas de caja negra.","Especifica como debe ser la documentación de pruebas."],"h":["También conocido como el Estándar para la Documentación del software de pruebas.","Especifica la forma de un conjunto de documentos para su uso en etapas definidas.","Incluye plan de pruebas, casos de prueba e informes de resultados."],"c":3,"e":"El IEEE 829-2008 es un documento estándar que especifica la forma de un conjunto de documentos para su uso en etapas definidas de pruebas de software, estableciendo una estructura determinada para la documentación.","d":2,"id":"q127","unit":"UF2406-UD6"},{"q":"Enunciado: Los factores directos de calidad...","o":["Los que el cliente aprecia de un vistazo.","Uno de ellos es la facilidad de uso.","Son los que se pueden medir directamente sobre el producto.","Ninguna de las anteriores es correcta."],"h":["Se contraponen a los factores indirectos.","Ejemplos incluyen el tiempo de ejecución u ocupación de memoria.","No dependen de la apreciación subjetiva del usuario final."],"c":2,"e":"Los factores directos son aquellos que se pueden medir directamente sobre el producto desarrollado, como el tiempo de ejecución, tiempo de respuesta u ocupación de memoria.","d":1,"id":"q128","unit":"UF2406-UD5"},{"q":"Enunciado: La calidad estructural del software...","o":["Se refiere a la infraestructura que lo soporta.","Se refiere a la forma en que cumple los requisitos funcionales.","Se refiere al modo en que este cumple con los requisitos no funcionales.","Sólo se mide a través de las pruebas."],"h":["Se evalúa analizando el código fuente y la arquitectura.","Se relaciona con requisitos no funcionales como la robustez o mantenibilidad.","Se contrapone a la calidad funcional, que se mide con pruebas."],"c":2,"e":"La calidad estructural se refiere al modo en que el software cumple con los requisitos no funcionales y al grado en que el software se ha producido correctamente a nivel de arquitectura y código.","d":2,"id":"q129","unit":"UF2406-UD5"},{"q":"Enunciado: La mala calidad de una infraestructura de sistema:","o":["Está correlacionada con el alto impacto que tienen las interrupciones debidas a datos dañados y otros factores.","No afecta al coste de mantenimiento.","Sólo se aplica a sistemas embebidos.","No se aplica en sistemas ERP y CRM."],"h":["Afecta gravemente a los centros de aplicaciones empresariales.","Provoca sobrecostos y desperdicio de recursos (hasta un 45% del tiempo de desarrollo).","Está fuertemente ligada a brechas de seguridad y cortes de aplicación."],"c":0,"e":"Estudios demuestran que la mala calidad de la infraestructura está fuertemente correlacionada con el alto impacto de las interrupciones en los negocios debido a datos dañados, cortes de aplicación y problemas de rendimiento.","d":2,"id":"q130","unit":"UF2406-UD5"},{"q":"Enunciado: La fiabilidad:","o":["Sólo se aplica en entornos empresariales.","Es esencial en sistemas de alta velocidad de ejecución.","Es un atributo de resistencia y solidez estructural.","Todas las respuestas son incorrectas."],"h":["Mide el nivel de riesgo y la probabilidad de fallos potenciales.","También mide los defectos inyectados debido a las modificaciones.","Su meta es reducir y prevenir el tiempo de inactividad de las aplicaciones."],"c":2,"e":"La fiabilidad es un atributo de resistencia y solidez estructural que mide el nivel de riesgo y la probabilidad de fallos potenciales de las aplicaciones.","d":2,"id":"q131","unit":"UF2406-UD5"},{"q":"Enunciado: La medición de la calidad del software:","o":["Consiste en cuantificar en qué medida un sistema posee características deseables.","Es realizada exclusivamente por los programadores.","Solamente se aplica en sistemas o proyectos de gran envergadura.","Es una medida de los atributos de código adecuados del sistema."],"h":["Se puede realizar a través de medios cualitativos, cuantitativos o una mezcla de ambos.","Para cada característica deseable debe haber atributos medibles.","Es un requisito previo para todas las disciplinas de la ingeniería."],"c":0,"e":"La medición de la calidad del software es cuantificar en qué medida un sistema o software posee características deseables, a través de medios cualitativos, cuantitativos o una mezcla de ambos.","d":1,"id":"q132","unit":"UF2406-UD5"},{"q":"Enunciado: El análisis estructural de calidad y la medición...","o":["Se realizan a través del análisis del código, la arquitectura, plataformas de software y esquemas de bases de datos.","Miden únicamente el esquema de la base de datos.","Se realizan siguiendo los principios de fiabilidad y exhaustividad.","Ninguna de las respuestas es correcta."],"h":["Se realiza en relación a los principios y normas que definen la arquitectura conceptual y lógica.","Es distinto del análisis básico de búsqueda de errores locales.","Evalúa atributos estáticos de calidad."],"c":0,"e":"El análisis estructural de calidad y la medición se realiza a través del análisis del código fuente, la arquitectura, plataforma de software y esquemas de bases de datos en relación a los principios y normas establecidos.","d":3,"id":"q133","unit":"UF2406-UD5"},{"q":"Enunciado: La mantenibilidad:","o":["Está relacionada con el concepto de deuda técnica.","Ha de medirse solo en los sistemas empotrados.","Se debe cuidar solo si se prevé que el sistema va a fallar a menudo.","Una baja mantenibilidad siempre tiene su origen en la falta de tiempo."],"h":["Incluye conceptos de modularidad, comprensibilidad y reutilización.","Es una expresión de los costes derivados de la falta de mantenimiento.","Suele ser resultado de miles de violaciones menores de buenas prácticas."],"c":0,"e":"La mantenibilidad está estrechamente relacionada con el concepto de deuda técnica, que es una expresión de los costes derivados de la falta de mantenimiento.","d":2,"id":"q134","unit":"UF2406-UD5"},{"q":"Enunciado: ¿Qué atributo NO es de los que deberían tener las métricas de software?","o":["Empíricas e intuitivas.","Simples y sencillas de calcular.","Subjetivas y objetivas.","Consistentes en el empleo de unidades y tamaños."],"h":["Deben producir un resultado no ambiguo.","Deben basarse en el modelo de análisis o diseño.","La subjetividad va en contra de la consistencia y objetividad requerida."],"c":2,"e":"Las métricas deben ser consistentes y objetivas (producir un resultado no ambiguo). La subjetividad no es un atributo deseable en una métrica de software.","d":2,"id":"q135","unit":"UF2406-UD5"},{"q":"Enunciado: Las normas ISO 9000:","o":["Determinan cómo se deben formar a los programadores en un entorno de calidad.","Indican los documentos de calidad que debe generar una organización.","Establecen los requisitos de un sistema de control de calidad.","Indican cómo deben hacerse las mediciones de calidad del software."],"h":["Son un grupo de estándares internacionales de administración.","Son genéricas, no específicas para un producto.","Documentan qué elementos usar para mantener un sistema eficiente de calidad en la empresa."],"c":2,"e":"La serie de normas ISO-9000 establece los requisitos básicos que debe de cumplir un sistema de control que garantice productos o servicios de calidad consistente.","d":1,"id":"q136","unit":"UF2406-UD5"},{"q":"Enunciado: El modelo de madurez del software CMM:","o":["Indica cómo cumple la normativa ISO una organización.","Detalla las tareas que se tienen que realizar conforme a la calidad.","Sirve de referencia para indicar el estado de I+D de una empresa.","Detalla cinco niveles inclusivos para determinar la madurez del proceso de desarrollo de una organización."],"h":["Sus siglas son Software Capability Maturity Model.","Los niveles son: Inicial, Repetible, Definido, Gestionado y Optimizado.","Para alcanzar un nivel, se deben haber logrado y mantenido todos los anteriores."],"c":3,"e":"En el Modelo de Madurez de la Capacidad del Software (SW-CMM) se detallan áreas clave del proceso agrupadas en cinco niveles inclusivos para determinar el estado de la madurez del proceso de desarrollo.","d":2,"id":"q137","unit":"UF2406-UD5"},{"q":"Enunciado: Sobre las pruebas de integración:","o":["Sólo se usan pruebas de caja blanca.","Un resguardo simula un subprograma subordinado.","Un controlador simula un subprograma subordinado.","Sólo se usan pruebas de caja negra."],"h":["Es una técnica sistemática para construir la estructura del programa.","Detecta errores asociados con la interacción entre módulos.","El controlador simula el módulo superior, no el subordinado."],"c":1,"e":"Los resguardos (stubs) sirven para reemplazar módulos que están subordinados (es decir, son llamados) al componente que hay que probar durante las pruebas de integración.","d":2,"id":"q138","unit":"UF2406-UD6"},{"q":"Enunciado: Sobre las pruebas de validación:","o":["Sirven para detectar errores de compilación.","La prueba beta se lleva a cabo por clientes en el lugar de desarrollo.","La prueba alfa se lleva a cabo por un cliente en el lugar de desarrollo.","Se prueban exhaustivamente cada clase antes de integrarla."],"h":["Se consigue cuando el software funciona según las expectativas razonables del cliente.","La prueba beta es en el lugar de trabajo del cliente, sin el desarrollador.","La prueba alfa es en el lugar de desarrollo, con el desarrollador como observador."],"c":2,"e":"La prueba alfa se lleva a cabo por un cliente, en el lugar de desarrollo, usando el software de forma natural con el desarrollador como observador del usuario y registrando los errores.","d":1,"id":"q139","unit":"UF2406-UD6"},{"q":"Enunciado: Sobre la prueba del camino básico:","o":["Utiliza la complejidad ciclomática.","Es un método de caja negra.","Se han de ejecutar cada ruta del programa dos veces.","Se han de probar la mitad de los nodos predicado al menos."],"h":["Es una técnica de prueba de caja blanca propuesta por Tom McCabe.","Permite obtener una medida de la complejidad lógica de un programa.","Garantiza que se ejecuta por lo menos una vez cada sentencia del programa."],"c":0,"e":"La prueba del camino básico utiliza la complejidad ciclomática, que proporciona una medición cuantitativa de la complejidad lógica y define el número de caminos independientes del conjunto básico.","d":2,"id":"q140","unit":"UF2406-UD6"},{"q":"Enunciado: Sobre las pruebas de bucles:","o":["Se prueba el límite superior del bucle.","Los bucles simples se prueban una vez.","Con los bucles anidados se usa una estrategia diferente que con los bucles simples.","Se prueba el límite inferior del bucle."],"h":["Se centra exclusivamente en la validez de las construcciones de bucles.","Extender el enfoque de bucles simples a anidados aumentaría las pruebas geométricamente.","Se comienza por el bucle más interior manteniendo los externos en valores mínimos."],"c":2,"e":"Con los bucles anidados se usa una estrategia diferente (comenzando por el más interior y manteniendo los externos en sus valores mínimos) para evitar un número impracticable de pruebas.","d":2,"id":"q141","unit":"UF2406-UD6"},{"q":"Enunciado: La depuración de programas es el proceso por el que:","o":["Se identifican y corrigen errores de programación en dicho programa.","Se identifican fallos en dicho programa.","Se identifican fallos de compilación en dicho programa.","Ninguna respuesta es válida."],"h":["También se le conoce como debugging.","Implica descubrir errores e identificar qué zonas del programa los producen.","Se utiliza un depurador para ejecutar el programa línea a línea o paso a paso."],"c":0,"e":"La depuración de programas es el proceso por el cual se identifican y corrigen errores de programación, descubriendo qué zonas del programa los producen.","d":1,"id":"q142","unit":"UF2406-UD6"},{"q":"Enunciado: Si se tienen varias pruebas JUnit:","o":["Se pueden combinar en un conjunto de pruebas.","Siempre han de ejecutarse manualmente una a una.","JUnit no permite más de una prueba a la vez.","Siempre se ejecutan en el mismo orden."],"h":["Se utiliza la anotación @RunWith(Suite.class).","Permite ejecutar todas las clases de prueba en esa suite en el orden especificado.","Facilita la organización de pruebas complejas."],"c":0,"e":"Si se tienen varias clases de prueba, se pueden combinar en un conjunto de pruebas (Suite). La ejecución de un conjunto de pruebas ejecutará todas las clases de prueba en esa suite en el orden especificado.","d":2,"id":"q143","unit":"UF2406-UD6"},{"q":"Enunciado: En la ejecución de un caso de pruebas:","o":["Nunca se deben de automatizar su ejecución.","Hay dos métodos, manual y automatizado.","Se puede obviar el formato de JUnit.","Se tienen que indicar si es una prueba de integración."],"h":["Dependiendo de la naturaleza de la prueba, se suele usar una combinación de ambos.","La automatización es útil para pruebas de regresión.","La prueba manual permite detectar errores no previstos por los scripts."],"c":1,"e":"Hay dos métodos utilizados en la ejecución de casos de prueba: manuales y automatizados. Dependiendo de la naturaleza de la prueba, una combinación de ambos suele ser el mejor método.","d":1,"id":"q144","unit":"UF2406-UD6"},{"q":"Enunciado: Un script de prueba en las pruebas de software es:","o":["Un documento que detalla un enfoque sistemático.","Un conjunto de instrucciones que se van a ejecutar en el sistema sometido a prueba.","Un programa que solo se ejecuta manualmente.","Una herramienta de gestión de configuración."],"h":["Puede ser manual o automatizado.","En la automatización, es un corto programa escrito en un lenguaje de programación.","Su objetivo es comprobar que el sistema funciona como se esperaba."],"c":1,"e":"Un script de prueba es un conjunto de instrucciones (o un corto programa) que se ejecuta en el sistema sometido a prueba para comprobar que su funcionalidad es la esperada.","d":1,"id":"q145","unit":"UF2406-UD6"},{"q":"Enunciado: Idealmente el software:","o":["Debe pasar al menos el 50% de las pruebas.","Debe de satisfacer la mitad de los requisitos.","Debe satisfacer todos los requisitos.","Debe de liberarse cuanto antes para que el usuario detecte los errores lo antes posible."],"h":["Desde el diseño, cada requisito debe abordarse en cada documento único.","La matriz de trazabilidad ayuda a verificar esto.","Si hay celdas vacías en la matriz, un requisito no se ha abordado correctamente."],"c":2,"e":"Idealmente, el software debe satisfacer por completo el conjunto de requisitos. Desde el diseño, cada requisito debe abordarse en cada documento único en el proceso de software.","d":1,"id":"q146","unit":"UF2406-UD6"},{"q":"Enunciado: El estándar IEEE 829-2008:","o":["Especifica cómo realizar las pruebas de software.","Especifica cómo realizar pruebas de caja blanca.","Especifica cómo realizar pruebas de caja negra.","Especifica cómo debe ser la documentación de pruebas."],"h":["También conocido como el Estándar para la Documentación del software de pruebas.","Especifica la forma de un conjunto de documentos para su uso en etapas definidas.","Incluye plan de pruebas, casos de prueba e informes de resultados."],"c":3,"e":"El IEEE 829-2008 es un documento estándar que especifica la forma de un conjunto de documentos para su uso en etapas definidas de pruebas de software, estableciendo una estructura determinada para la documentación.","d":2,"id":"q147","unit":"UF2406-UD6"},{"q":"Enunciado: Un programa perfectamente compilado:","o":["Generalmente no va a ocasionar ningún problema.","NUNCA puede tener un error ya que se ha compilado perfectamente sin errores.","Puede generar otros errores cuando se ejecuta.","Ninguna de las anteriores es correcta."],"h":["Puede no tener errores de sintaxis.","Puede generar errores en tiempo de ejecución.","A estos errores se les conoce como excepciones."],"c":2,"e":"Un programa perfectamente compilado en el que no existen errores de sintaxis, puede generar otros tipos de errores que pueden aparecer en tiempo de ejecución. A estos errores se les conoce como excepciones.","d":1,"id":"q148","unit":"UF2406-UD7"},{"q":"Enunciado: Una excepción es:","o":["Una instrucción de Java.","Una clase de Java que hereda de Error.","Un evento que se produce durante la ejecución de un programa que interrumpe su flujo normal de instrucciones.","Una clase de Java incorporada al paquete IOException."],"h":["El término es abreviatura de \"caso excepcional\".","Cuando ocurre, el método crea un objeto y lo entrega al sistema de tiempo de ejecución.","Contiene información sobre el error, incluyendo su tipo y el estado del programa."],"c":2,"e":"Una excepción es un evento que se produce durante la ejecución de un programa, que interrumpe el flujo normal de las instrucciones del programa.","d":1,"id":"q149","unit":"UF2406-UD7"},{"q":"Enunciado: Las tres clases de excepciones que hay son:","o":["Las excepciones comprobadas, las no comprobadas y los errores.","Los errores y las excepciones propiamente dichas.","Las Throwable y las IOException.","Solo hay una clase de excepciones en Java."],"h":["Una es la que el programador debe verificar (checked).","Otra son condiciones externas que la aplicación no puede anticipar (Error).","La tercera son condiciones internas, como errores lógicos (RuntimeException)."],"c":0,"e":"Las tres clases de excepciones que hay en Java son excepciones comprobadas, errores y excepciones en tiempo de ejecución (no comprobadas).","d":2,"id":"q150","unit":"UF2406-UD7"},{"q":"Enunciado: Las excepciones se capturan...","o":["Con la sentencia throw.","Mediante un bloque finally{...}.","Mediante un bloque try{...} catch{...}.","Con la sentencia throws."],"h":["Se utiliza una estructura de control específica.","El bloque que la contiene es \"try\".","El bloque que la maneja es \"catch\"."],"c":2,"e":"Para poder capturar excepciones, emplearemos la estructura de captura de excepciones try-catch-finally. El bloque catch contiene el código que se ejecuta cuando se invoca el controlador de excepciones.","d":1,"id":"q151","unit":"UF2406-UD7"},{"q":"Enunciado: Las excepciones se lanzan...","o":["Con la sentencia throw.","Mediante un bloque finally{...}.","Mediante un bloque try{...} catch{...}.","Con la sentencia throws."],"h":["Se utiliza una palabra clave específica en Java.","Esta palabra clave es \"throw\".","No debe confundirse con \"throws\", que se usa en la firma del método para declarar que puede lanzar una excepción."],"c":0,"e":"El hecho de que se produzca la creación de un objeto de excepción y entregarla al sistema de tiempo de ejecución se llama lanzar una excepción, y se realiza con la sentencia throw.","d":1,"id":"q152","unit":"UF2406-UD7"},{"q":"Enunciado: El bloque finally...","o":["Es una herramienta clave para la prevención de pérdida de recursos.","Es obligatorio incluirlo.","Se coloca antes del try.","Ninguna de las respuestas es correcta."],"h":["Siempre se ejecuta al salir del bloque try.","Es útil para código de limpieza.","Permite cerrar archivos o liberar recursos aunque se produzca una excepción."],"c":0,"e":"El bloque finally es una herramienta clave para la prevención de pérdidas de recursos. Siempre hay que cerrar un archivo o de lo contrario se pueden ocupar recursos y bloquear estos.","d":2,"id":"q153","unit":"UF2406-UD7"},{"q":"Enunciado: La principal ventaja de las excepciones es:","o":["Separa el código normal del código de detección y recuperación de errores.","Que el código es código espagueti.","Un método debe recuperarse de los errores que genere.","Solo se usa en lenguaje C."],"h":["Evita el \"código espagueti\".","Organiza el trabajo de manera más eficaz.","Permite escribir el flujo principal del código y trabajar con los casos excepcionales en otras partes."],"c":0,"e":"La principal ventaja de las excepciones es separar el código de manejo de errores del código \"normal\", evitando que la detección de errores, la presentación de la información y el proceso de datos conduzcan a un \"código espagueti\" confuso.","d":2,"id":"q154","unit":"UF2406-UD7"},{"q":"Enunciado: Un método puede re-lanzar una excepción...","o":["No, nunca.","De hecho siempre deben re-lanzarse las excepciones.","Y así la puede capturar otro método que esté en la parte superior de la pila.","Solamente las que están por debajo en la jerarquía de IOException."],"h":["Permite que la excepción suba en la pila de llamadas.","Un método superior en la pila puede atraparla.","Esto evita que los métodos intermedios tengan que manejar errores que no les incumben."],"c":2,"e":"Un método puede re-lanzar una excepción lanzada dentro de él, lo que permite que un método que esté más arriba en la pila de llamadas pueda atraparla y manejarla.","d":2,"id":"q155","unit":"UF2406-UD7"},{"q":"Enunciado: ¿Se puede incluir información relevante en un objeto de excepción?","o":["No es recomendable trabajar así.","Solamente las excepciones que se van a re-lanzar.","Sí, una excepción puede incluir información en el objeto asociado.","Las excepciones solo se pueden capturar, y no se usan para transmitir información."],"h":["Una excepción es realmente un objeto con todas sus características.","El programador puede incluir información sobre el error.","Se puede obtener dicha información solicitándola al objeto en el catch."],"c":2,"e":"Debido a que una excepción es realmente un objeto, el programador puede incluir toda la información que desee en ese objeto (como un mensaje o un código de error) y obtenerla en el bloque catch.","d":2,"id":"q156","unit":"UF2406-UD7"},{"q":"Enunciado: La información que se incluya en un objeto excepción puede ser:","o":["No se puede incluir información en un objeto excepción.","Solamente cadenas de texto.","Solamente un código de error numérico.","No solamente cadenas, sino de cualquier tipo válido."],"h":["No se limita a cadenas de texto.","Se pueden agregar métodos necesarios a la clase que implementa la excepción.","Por ejemplo, se puede almacenar y recuperar un valor de temperatura o un objeto específico."],"c":3,"e":"Se puede añadir más información que simplemente una cadena; basta con agregar los métodos necesarios a la clase que implementa la excepción para almacenar y recuperar cualquier tipo de dato válido.","d":3,"id":"q157","unit":"UF2406-UD7"},{"q":"¿En cuántas etapas se divide el diseño de una base de datos?","o":["En dos: conceptual y lógica.","En dos: conceptual y física.","En tres: conceptual, lógica y física.","En cuatro: análisis, diseño, implementación y pruebas."],"h":["La primera es independiente de la tecnología.","La segunda transforma el modelo E-R a relacional.","La tercera se refiere a la implementación en memoria secundaria."],"c":2,"e":"El diseño de una base de datos se divide en tres etapas: diseño conceptual, diseño lógico y diseño físico.","d":1,"id":"q158","unit":"UF2405-UD4"},{"q":"¿Qué es una entidad en el modelo Entidad-Relación?","o":["Son las características que definen un atributo.","Es la representación de un objeto en el mundo real, distinguible del resto.","Es la unión entre atributos.","Ninguna de las anteriores."],"h":["Puede ser tangible (alumno) o intangible (asignatura).","Se representa gráficamente con un rectángulo.","Posee atributos que la describen."],"c":1,"e":"Una entidad es la representación de un objeto del mundo real, distinguible de otros objetos, que se describe mediante un conjunto de atributos.","d":1,"id":"q159","unit":"UF2405-UD4"},{"q":"Para que una entidad sea distinguible del resto será necesario tener un atributo o varios que la identifiquen, estos atributos recibirán el nombre de...","o":["Clave ajena.","Clave foránea.","Clave candidata.","Clave primaria."],"h":["Garantiza la integridad de la entidad.","No puede contener valores nulos.","Identifica de forma única cada tupla o fila de la tabla."],"c":3,"e":"La clave primaria es el atributo (o conjunto de atributos) que identifica de forma única a cada ocurrencia de una entidad, diferenciándola del resto.","d":2,"id":"q160","unit":"UF2405-UD4"},{"q":"¿Qué significa la cardinalidad de una relación?","o":["Es el tipo de correspondencia que se establecerá entre las entidades, reflejando el número de ocurrencias.","Es la correspondencia entre atributos.","No refleja el número de ocurrencias.","Es el tipo de correspondencia que no se establecerá."],"h":["Define cuántas instancias de una entidad se relacionan con otra.","Puede ser 1:1, 1:N o M:N.","Se indica en los extremos de la línea de relación en el diagrama."],"c":0,"e":"La cardinalidad es el tipo de correspondencia que se establecerá entre las entidades de la relación, reflejando el número de ocurrencias de una entidad con las ocurrencias de la otra entidad con la que existe una asociación.","d":2,"id":"q161","unit":"UF2405-UD4"},{"q":"¿Qué tres operaciones fundamentales del álgebra relacional permitirán la creación de nuevas tablas a partir de las ya existentes?","o":["Diseño lógico, conceptual y físico.","Selección, proyección y concatenación o unión.","Lógica, proyección y concatenación.","Selección, lógica y concatenación."],"h":["Una filtra filas según una condición.","Otra filtra columnas específicas.","La tercera combina registros de dos tablas."],"c":1,"e":"Las operaciones fundamentales del álgebra relacional en las que se basa SQL son: Selección, Proyección y Concatenación o unión.","d":2,"id":"q162","unit":"UF2405-UD4"},{"q":"¿Cuáles son los tipos de lenguajes utilizados según las operaciones que realizan en un SGBD?","o":["Solo DCL.","Solo DDL.","Solo DML.","DCL, DDL y DML."],"h":["Uno define la estructura (CREATE).","Otro manipula los datos (SELECT).","Otro controla los permisos y accesos (GRANT)."],"c":3,"e":"Los lenguajes de un SGBD se clasifican principalmente en DDL (Definición de Datos), DML (Manipulación de Datos) y DCL (Control de Datos).","d":1,"id":"q163","unit":"UF2405-UD4"},{"q":"SQL es un lenguaje...","o":["No declarativo.","Declarativo.","Declarativo y no procedimental.","Declarativo y procedimental."],"h":["El usuario describe QUÉ quiere obtener, no CÓMO obtenerlo.","No se basa en algoritmos paso a paso.","Está estandarizado por ANSI/ISO."],"c":2,"e":"SQL es un lenguaje declarativo y no procedimental, lo que significa que se basa en describir las condiciones y restricciones de los datos deseados, dejando al SGBD la tarea de determinar cómo ejecutar la consulta.","d":2,"id":"q164","unit":"UF2405-UD4"},{"q":"¿Qué es el lenguaje de manipulación de datos (DML)?","o":["Creación de estructuras de datos.","Consulta y modificación de datos.","Control de acceso a la base de datos.","Definición de datos."],"h":["Incluye sentencias como SELECT, INSERT, UPDATE, DELETE.","Permite a los usuarios interactuar con la información almacenada.","No se usa para crear tablas, sino para manejar su contenido."],"c":1,"e":"El DML (Data Manipulation Language) es el lenguaje mediante el cual uno o varios usuarios pueden realizar operaciones de consulta, modificación y eliminación de los datos contenidos en una base de datos.","d":1,"id":"q165","unit":"UF2405-UD7"},{"q":"Las sentencias que forman el lenguaje DML son:","o":["CREATE, ALTER, DROP.","GRANT, REVOKE.","SELECT, INSERT, UPDATE, DELETE.","COMMIT, ROLLBACK."],"h":["Son las operaciones básicas sobre los registros.","Permiten leer, añadir, cambiar y borrar información.","No definen la estructura, solo la manipulan."],"c":2,"e":"Los elementos que conforman el lenguaje DML son las sentencias SELECT (consulta), INSERT (inserción), UPDATE (modificación) y DELETE (eliminación).","d":1,"id":"q166","unit":"UF2405-UD7"},{"q":"¿Qué sentencia se utiliza para insertar datos en una tabla?","o":["UPDATE.","DELETE.","INSERT.","DROP."],"h":["Añade nuevas filas a una tabla existente.","Utiliza la cláusula VALUES para especificar los datos.","Es la operación opuesta a borrar."],"c":2,"e":"La sentencia INSERT se utiliza para introducir datos en una o varias filas de una tabla de una base de datos.","d":1,"id":"q167","unit":"UF2405-UD7"},{"q":"La sentencia UPDATE se utiliza para...","o":["Insertar una fila.","Modificar y actualizar datos de una o varias filas de una tabla.","Eliminar una tabla.","Crear una vista."],"h":["Cambia el valor de uno o varios atributos.","Suele ir acompañada de la cláusula WHERE para filtrar qué filas se modifican.","No añade filas nuevas, solo altera las existentes."],"c":1,"e":"La sentencia UPDATE se utiliza para modificar o actualizar datos de una o varias filas de una única tabla de una base de datos.","d":1,"id":"q168","unit":"UF2405-UD7"},{"q":"Para eliminar toda la definición de una tabla (estructura y datos) se utiliza la sentencia:","o":["DELETE.","TRUNCATE.","DROP.","ALTER."],"h":["Elimina el objeto por completo de la base de datos.","No solo borra las filas, sino también la estructura.","Es una operación del DDL, no del DML."],"c":2,"e":"La sentencia DROP elimina por completo la tabla, desapareciendo de la base de datos tanto su estructura como el contenido de la misma.","d":2,"id":"q169","unit":"UF2405-UD6"},{"q":"¿Qué tipo de combinaciones de tablas existen en SQL para agregar conjuntos de datos?","o":["JOIN y UNION.","Solo JOIN.","COMMIT y UNION.","Solo UNION."],"h":["Una combina columnas de varias tablas horizontalmente (JOIN).","Otra combina filas de múltiples consultas verticalmente (UNION).","Son fundamentales para consultas complejas."],"c":0,"e":"Los tipos principales de combinaciones de tablas para agregar conjuntos de datos en una consulta son JOIN (combinación de columnas) y UNION (combinación de filas).","d":2,"id":"q170","unit":"UF2405-UD7"},{"q":"La sentencia UNION puede llevar las siguientes cláusulas:","o":["WHERE, GROUP BY y HAVING.","ORDER BY, WHERE y GROUP BY.","ORDER BY y HAVING.","WHERE, GROUP BY, HAVING y ORDER BY."],"h":["Filtra resultados (WHERE, HAVING).","Agrupa datos (GROUP BY).","Ordena el resultado final (ORDER BY). Todas son opcionales pero compatibles."],"c":3,"e":"Las cláusulas WHERE, GROUP BY, HAVING y ORDER BY son cláusulas opcionales que pueden aparecer dentro de las sentencias que se combinan con UNION.","d":3,"id":"q171","unit":"UF2405-UD7"},{"q":"¿Qué es una excepción en Java?","o":["Una instrucción de compilación.","Un evento que interrumpe el flujo normal de instrucciones durante la ejecución.","Un error de sintaxis detectado antes de compilar.","Una clase que hereda de Object directamente."],"h":["Ocurre en tiempo de ejecución.","Puede ser capturada y manejada para evitar que el programa termine abruptamente.","Deriva de la clase Throwable."],"c":1,"e":"Una excepción es un evento que se produce durante la ejecución de un programa, que interrumpe el flujo normal de las instrucciones del programa.","d":1,"id":"q172","unit":"UF2406-UD7"},{"q":"Las tres clases de excepciones que hay en Java son:","o":["Comprobadas, no comprobadas (tiempo de ejecución) y errores.","Sintácticas, lógicas y de ejecución.","De entrada, de salida y de red.","Solo existe la clase Exception."],"h":["El programador debe verificar las \"comprobadas\" (checked).","Las \"no comprobadas\" suelen ser errores de programación (RuntimeException).","Los \"errores\" (Error) son problemas graves de la JVM."],"c":0,"e":"Las tres clases de excepciones en Java son: excepciones comprobadas, excepciones en tiempo de ejecución (no comprobadas) y errores.","d":2,"id":"q173","unit":"UF2406-UD7"},{"q":"Las excepciones se capturan...","o":["Con la sentencia throw.","Mediante un bloque finally.","Mediante una estructura try-catch.","Con la sentencia throws."],"h":["Se intenta ejecutar código en un bloque de prueba.","Si falla, se atrapa en otro bloque específico.","El bloque que atrapa empieza por la palabra \"catch\"."],"c":2,"e":"Para poder capturar excepciones, se emplea la estructura de captura de excepciones try-catch-finally. El bloque catch contiene el código que se ejecuta cuando se invoca el controlador de excepciones.","d":1,"id":"q174","unit":"UF2406-UD7"},{"q":"Las excepciones se lanzan...","o":["Con la sentencia throw.","Mediante un bloque finally.","Mediante un bloque try.","Con la sentencia throws (en la firma del método)."],"h":["Es la acción de generar el objeto excepción manualmente.","Se usa una palabra clave específica seguida del objeto.","No debe confundirse con \"throws\", que solo declara que un método puede lanzarla."],"c":0,"e":"El hecho de que se produzca la creación de un objeto de excepción y entregarla al sistema de tiempo de ejecución se llama lanzar una excepción, y se realiza con la sentencia throw.","d":1,"id":"q175","unit":"UF2406-UD7"},{"q":"El bloque finally...","o":["Es una herramienta clave para la prevención de pérdida de recursos.","Es obligatorio incluirlo siempre.","Se coloca antes del try.","Solo se ejecuta si hay una excepción."],"h":["Se ejecuta siempre, haya o no excepción.","Es ideal para cerrar archivos, conexiones o liberar memoria.","Evita fugas de recursos bloqueados."],"c":0,"e":"El bloque finally es una herramienta clave para la prevención de pérdidas de recursos. Siempre hay que cerrar un archivo o liberar recursos, y finally asegura que este código se ejecute independientemente de si ocurrió una excepción.","d":2,"id":"q176","unit":"UF2406-UD7"},{"q":"Si el software es una primera versión sobre la que se va a seguir trabajando...","o":["No hace falta documentación de requisitos.","La documentación de diseño se puede eliminar.","La documentación de requisitos es muy útil como guía para el cambio.","No es necesario documentar nada."],"h":["El software evoluciona con el tiempo.","Saber qué se pidió originalmente ayuda a no romper funcionalidades existentes.","Facilita la gestión del cambio y la verificación."],"c":2,"e":"Si el software es una primera versión sobre la que más tarde se va a seguir trabajando, la documentación de los requisitos es muy útil en la gestión del cambio de software y verificar que no se ha deteriorado cuando se modifica.","d":2,"id":"q177","unit":"UF2406-UD8"},{"q":"La programación explicativa...","o":["No existe tal concepto.","Es un paradigma de programación estructurada.","Es el resultado de la aplicación práctica de la escritura de programación autoexplicativa en contextos reales.","Solo se practica en Java."],"h":["Propone separar código fuente y documentación, pero vinculados.","Busca que el código se entienda por sí mismo.","Donald Knuth abogó por ideas similares (programación literaria)."],"c":2,"e":"La programación explicativa es el resultado de la aplicación práctica de la escritura de programación autoexplicativa en contextos de programación real, proponiendo a menudo que el código fuente y la documentación se almacenen por separado pero vinculados dinámicamente.","d":3,"id":"q178","unit":"UF2406-UD8"},{"q":"Cuando se documenta el código...","o":["Se puede asumir que el usuario tendrá conocimientos avanzados.","No hay que incluir imágenes.","No se debe de asumir nada que el usuario deba saber.","Todas las respuestas son incorrectas."],"h":["La documentación debe ser clara para todos los niveles.","No dar por sentado conocimientos previos.","Explicar el \"por qué\", no solo el \"qué\"."],"c":2,"e":"Un principio importante al documentar es no asumir nada que el usuario deba saber. La documentación debe ser escrita de manera que cualquier persona con conocimientos básicos pueda leerla y aprender a utilizar correctamente el sistema.","d":2,"id":"q179","unit":"UF2406-UD8"},{"q":"Los estándares de documentación:","o":["Convienen utilizarlos siempre.","No es necesario que se usen, son orientativos.","No existe ninguno para Java.","Ninguna de las respuestas es correcta."],"h":["Ayudan a mantener la coherencia en el proyecto.","Facilitan que otros desarrolladores entiendan el código rápidamente.","Javadoc es un ejemplo de estándar ampliamente aceptado."],"c":0,"e":"Conviene seguir las pautas de documentación corporativa y estándares, ya que ayudan a asegurar que la información importante no se excluye y permiten una lectura más fácil y uniforme por parte de los usuarios del sistema.","d":1,"id":"q180","unit":"UF2406-UD8"},{"q":"Se ha de documentar el código...","o":["Para facilitar su mantenimiento y reutilización.","Principalmente por motivos estéticos.","Porque lo indican los estándares ISO únicamente.","Solamente en organizaciones muy grandes."],"h":["Ayuda a otros programadores (o a ti mismo en el futuro).","Explica qué hace el código y por qué.","Es una necesidad práctica, no un lujo."],"c":0,"e":"Se ha de documentar el código porque facilitaremos su mantenimiento y reutilización. Es una necesidad que se aprecia en su debida magnitud cuando hay errores que reparar o hay que extender el programa con nuevas capacidades.","d":1,"id":"q181","unit":"UF2406-UD8"},{"q":"La documentación de Javadoc:","o":["Se basa en etiquetas que empiezan por #.","Si no se incluye, la clase no compila.","En ella existen etiquetas de bloque y etiquetas en texto.","Se usa solo para documentar excepciones."],"h":["Usa comentarios especiales con formato /** ... */.","Tiene etiquetas como @param, @return.","La herramienta genera archivos HTML navegables."],"c":2,"e":"En los comentarios de documentación de Javadoc existen dos tipos generales de etiquetas: etiquetas de bloque (que comienzan con @) y etiquetas en texto (que se definen entre llaves {@etiqueta}).","d":2,"id":"q182","unit":"UF2406-UD8"},{"q":"Para indicar el valor de retorno de un método en Javadoc...","o":["Se usa la etiqueta @param.","Se usa la etiqueta @version.","Se usa la etiqueta @return.","Se usa la etiqueta @throws."],"h":["Describe qué devuelve el método.","No se usa en métodos void.","Empieza con la letra 'r'."],"c":2,"e":"La etiqueta @return se utiliza en Javadoc para dejar explícito qué tipo o clase de valor devuelve un método y sus posibles rangos de valores. Se puede omitir en métodos que devuelven void.","d":1,"id":"q183","unit":"UF2406-UD8"},{"q":"Las descripciones de los métodos en Javadoc deben empezar...","o":["Por una frase nominal.","Con la etiqueta @methodDescription.","Con la etiqueta @throw.","Por una frase verbal."],"h":["Describe una acción.","Ejemplo: \"Devuelve la etiqueta\" en lugar de \"Este método obtiene...\".","Es una convención de estilo para la tercera persona descriptiva."],"c":3,"e":"Las descripciones de los métodos deben comenzar con una frase verbal (tercera persona descriptiva), ya que un método implementa una operación. Por ejemplo: \"Devuelve la etiqueta de este botón\".","d":2,"id":"q184","unit":"UF2406-UD8"}];
